// O bot responde em grupos e também em conversas privadas.
const $ = selector => document.querySelector(selector);
const $$ = selector => [...document.querySelectorAll(selector)];
const content = $('#content');
const modal = $('#modal');
const DEFAULT_DASHBOARD_CARDS = ['connection','messages','queue','last_reply','top_rules','errors','memory'];
const state = {
  dashboardRenderedAt: 0,
  view: 'dashboard', status: null, messages: [], synonyms: [], sectors: [], calculators: [], groups: [], settings: {},
  logs: [], diagnostics: [], conflicts: { count: 0, conflicts: [] }, analytics: null, backups: null,
  diagnosticStream: null, realtimeStream: null, selectedMessages: new Set(), diagnosticMode: localStorage.getItem('hub-diagnostic-mode') || 'simple',
  messageVisibleLimit: 30, messageLoadToken: 0, conflictOnly: false, messageObserver: null,
  messagePage: {total:0,nextCursor:'',loading:false,queryKey:'',limit:60},
  messageVirtual: {start:0,end:0,rowHeight:380,overscanRows:2,scrollHandler:null},
  messageViewMode: ['cards','list'].includes(localStorage.getItem('hub-message-view'))?localStorage.getItem('hub-message-view'):'cards',
  messageColumns: ['auto','1','2','3','4'].includes(localStorage.getItem('hub-message-columns'))?localStorage.getItem('hub-message-columns'):'auto',
  teacherImportPreview: null
};
const titles = {
  dashboard: 'Visão geral', messages: 'Mensagens automáticas', diagnostics: 'Diagnóstico em tempo real',
  calculators: 'Calculadoras', groups: 'Grupos', analytics: 'Estatísticas anônimas', settings: 'Configurações', logs: 'Registros'
};

function esc(value = '') { return String(value).replace(/[&<>'"]/g, c => ({ '&':'&amp;','<':'&lt;','>':'&gt;',"'":'&#39;','"':'&quot;' }[c])); }
function bool(value) { return ['1','true','yes','sim','on'].includes(String(value).toLowerCase()); }
function normalizeSearch(value=''){return String(value).toLowerCase().normalize('NFD').replace(/[\u0300-\u036f]/g,'').trim();}
function list(value) { return String(value || '').split(/[\n,;|]+/).map(item => item.trim()).filter(Boolean); }
function fmtDate(value) { if (!value) return '—'; try { return new Intl.DateTimeFormat('pt-BR',{dateStyle:'short',timeStyle:'short'}).format(new Date(value)); } catch { return value; } }
function fmtBytes(value) { const n=Number(value||0); if(!n)return'0 B'; const u=['B','KiB','MiB','GiB']; const i=Math.min(u.length-1,Math.floor(Math.log(n)/Math.log(1024))); return `${(n/1024**i).toFixed(i?1:0)} ${u[i]}`; }
function fmtDuration(seconds) { let n=Math.max(0,Number(seconds||0)); const d=Math.floor(n/86400); n%=86400; const h=Math.floor(n/3600); n%=3600; const m=Math.floor(n/60); return [d?`${d}d`:'',h?`${h}h`:'',`${m}min`].filter(Boolean).join(' '); }
function relativeTime(value) { if(!value)return'nenhuma ainda'; const seconds=Math.max(0,Math.round((Date.now()-new Date(value).getTime())/1000)); if(seconds<60)return`há ${seconds}s`; if(seconds<3600)return`há ${Math.floor(seconds/60)}min`; if(seconds<86400)return`há ${Math.floor(seconds/3600)}h`; return`há ${Math.floor(seconds/86400)}d`; }
function toast(message,error=false){const el=$('#toast');el.textContent=message;el.className=`toast${error?' error':''}`;el.hidden=false;clearTimeout(toast.timer);toast.timer=setTimeout(()=>{el.hidden=true;},4500);}
function badge(text,kind=''){return`<span class="badge ${kind}">${esc(text)}</span>`;}
function statCard(label,value,detail=''){return`<div class="card stat"><small>${esc(label)}</small><strong>${esc(value)}</strong>${detail?`<span class="muted">${esc(detail)}</span>`:''}</div>`;}
function downloadBlob(name, payload, type='application/json'){const blob=new Blob([payload],{type});const url=URL.createObjectURL(blob);const a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}

async function api(path, options={}) {
  const headers={...(options.headers||{})}; if(options.body!==undefined&&!headers['Content-Type'])headers['Content-Type']='application/json';
  const controller=new AbortController();const timeoutMs=Number(options.timeoutMs||8000);const timer=setTimeout(()=>controller.abort(),timeoutMs);
  try{
    const response=await fetch(path,{credentials:'same-origin',cache:'no-store',...options,headers,signal:options.signal||controller.signal});let payload=null;try{payload=await response.json();}catch{}
    if(response.status===401){showLogin(payload?.error||'Sessão encerrada.');throw new Error(payload?.error||'Sessão encerrada.');}
    if(!response.ok)throw new Error(payload?.error||`Erro HTTP ${response.status}`);return payload;
  }catch(error){if(error?.name==='AbortError')throw new Error('O painel local demorou para responder. Tente novamente.');throw error;}finally{clearTimeout(timer);}
}
function loginFeedback(message='',kind='error'){const box=$('#login-feedback');box.textContent=message;box.className=`login-feedback ${kind}`;box.hidden=!message;}
function showLogin(message=''){closeDiagnosticStream();closeRealtimeStream();$('#app').hidden=true;$('#login-screen').hidden=false;document.body.classList.add('login-only');history.replaceState({},'','/login');if(message)loginFeedback(message,'error');setTimeout(()=>$('#login-password').focus(),0);}
function showApp(){$('#login-screen').hidden=true;$('#app').hidden=false;document.body.classList.remove('login-only');history.replaceState({},'','/painel');}

$('#login-form').onsubmit=async event=>{event.preventDefault();const button=$('#login-submit');loginFeedback();button.disabled=true;button.textContent='⏳ Verificando…';try{await api('/api/login',{method:'POST',body:JSON.stringify({password:$('#login-password').value})});loginFeedback('✅ Senha correta. Abrindo o painel…','success');$('#login-password').value='';await loadAll();showApp();}catch(error){loginFeedback(`❌ ${error.message}`,'error');$('#login-password').select();}finally{button.disabled=false;button.textContent='🔐 Entrar';}};
$('#logout-admin').onclick=async()=>{try{await api('/api/logout',{method:'POST',body:'{}'});}catch{}showLogin('Sessão encerrada.');};
$('#nav').onclick=event=>{const button=event.target.closest('[data-view]');if(!button)return;if(state.view==='diagnostics'&&button.dataset.view!=='diagnostics')closeDiagnosticStream();state.view=button.dataset.view;$$('#nav button').forEach(item=>item.classList.toggle('active',item===button));render();};

let statusRefreshPromise=null;
async function loadAll(){const[status]=await Promise.all([api('/api/status')]);state.status=status;renderStatus();await render();openRealtimeStream();}
async function refreshStatus(){if(statusRefreshPromise)return statusRefreshPromise;statusRefreshPromise=(async()=>{try{const next=await api('/api/status',{timeoutMs:5000});state.status=next;renderStatus();if(state.view==='dashboard'&&Date.now()-state.dashboardRenderedAt>45000)renderDashboard();}catch(error){console.warn(error.message);}finally{statusRefreshPromise=null;}})();return statusRefreshPromise;}
let realtimeRefreshTimer=null;
function closeRealtimeStream(){if(state.realtimeStream){state.realtimeStream.close();state.realtimeStream=null;}clearTimeout(realtimeRefreshTimer);realtimeRefreshTimer=null;}
function scheduleRealtimeRefresh({rerender=false}={}){clearTimeout(realtimeRefreshTimer);realtimeRefreshTimer=setTimeout(async()=>{await refreshStatus();if(rerender&&['messages','dashboard','groups','analytics'].includes(state.view))render().catch(error=>console.warn(error.message));},120);}
function openRealtimeStream(){
  closeRealtimeStream();
  const stream=new EventSource('/api/events');
  const refreshOnlyTypes=new Set(['whatsapp-status','admin-task-progress','admin-task-completed','admin-task-failed','backup-created','links-checked','database-maintenance']);
  const refreshDataTypes=new Set(['database-change','data-changed','settings-changed']);
  const dispatchType=type=>{if(refreshDataTypes.has(type))scheduleRealtimeRefresh({rerender:true});else if(refreshOnlyTypes.has(type))scheduleRealtimeRefresh();};
  for(const type of refreshOnlyTypes)stream.addEventListener(type,()=>dispatchType(type));
  for(const type of refreshDataTypes)stream.addEventListener(type,()=>dispatchType(type));
  stream.addEventListener('realtime-batch',event=>{try{const payload=JSON.parse(event.data||'{}');const types=new Set((payload.events||[]).map(item=>item.type));scheduleRealtimeRefresh({rerender:[...types].some(type=>refreshDataTypes.has(type))});}catch{scheduleRealtimeRefresh();}});
  stream.onerror=()=>{};
  state.realtimeStream=stream;
}
function healthChip(icon,label,detail,kind='good'){return`<div class="health-chip ${kind}"><span>${icon}</span><div><strong>${esc(label)}</strong><small>${esc(detail)}</small></div></div>`;}
function renderStatus(){
  const wa=state.status?.whatsapp||{};const health=state.status?.health||{};const engine=health.engine||{};const stats=state.status?.stats||{};
  const ready=wa.state==='ready';const pending=['starting','connecting','authenticated','recovering','qr','resetting'].includes(wa.state);
  $('#top-status').textContent=ready?'WhatsApp conectado':pending?(wa.state==='qr'?'Aguardando QR code':'WhatsApp iniciando'):'WhatsApp desconectado';
  $('#top-status').className=`status-pill ${ready?'ready':pending?'pending':'offline'}`;$('#side-status').className=`status-dot ${ready?'ready':''}`;$('#side-status-text').textContent=ready?'Conectado':pending?'Iniciando':'Desconectado';$('#side-version').textContent=`v${state.status?.version||'0.9.8'} · local`;
  const staleMinutes=Math.max(10,Number(state.settings.dashboard_stale_minutes||120));const lastMs=engine.lastMessageAt?new Date(engine.lastMessageAt).getTime():0;const stale=ready&&((lastMs&&Date.now()-lastMs>staleMinutes*60000)||(!lastMs&&Number(health.process?.uptimeSeconds||0)>staleMinutes*60));
  const queueDepth=Number(wa.conversationQueueDepth||wa.outboundQueueDepth||0);const activeConversations=Number(wa.activeConversationCount||0);const trackedConversations=Number(wa.trackedConversationCount||activeConversations);const pausedUntil=wa.outboundPausedUntil?new Date(wa.outboundPausedUntil).getTime():0;
  const uncertainCount=Number(wa.persistentDeliveries?.uncertain||0);const pendingLate=Number(wa.pendingLateSendCount||0);
  const chips=[
    healthChip(ready?'🟢':pending?'🟡':'🔴',ready?'WhatsApp conectado':pending?'WhatsApp iniciando':'WhatsApp desconectado',wa.message||wa.state,ready?'good':pending?'warn':'bad'),
    healthChip(stale?'🔴':engine.lastMessageAt?'🟢':'🟡',stale?'WhatsApp conectado, mas sem mensagens':engine.lastMessageAt?'Recebendo mensagens':'Aguardando mensagem',engine.lastMessageAt?`Última ${relativeTime(engine.lastMessageAt)}`:'Nenhuma recebida nesta execução',stale?'bad':engine.lastMessageAt?'good':'warn'),
    healthChip(pausedUntil>Date.now()?'🔴':'🟢',pausedUntil>Date.now()?'Envios temporariamente pausados':'Respostas sem atraso artificial',`${activeConversations} conversa(s) ativa(s) · ${queueDepth} aguardando`,pausedUntil>Date.now()?'bad':'good'),
    healthChip('🟢',`${stats.messageCount||0} mensagens ativas`,`${stats.inactiveMessageCount||0} inativas · ${stats.archivedMessageCount||0} arquivadas`,'good'),
    healthChip(engine.lastReplyAt?'🟢':'🟡','Última resposta',engine.lastReplyAt?relativeTime(engine.lastReplyAt):'Nenhuma nesta execução',engine.lastReplyAt?'good':'warn'),
    ...(uncertainCount?[healthChip('🟠',`${uncertainCount} envio(s) com resultado desconhecido`,pendingLate?`${pendingLate} ainda em reconciliação`:'Revisão manual necessária','warn')]:[])
  ];
  const bar=$('#global-health');if(bar)bar.innerHTML=chips.join('');
}
function cleanupMessageVirtualization(){if(state.messageVirtual.scrollHandler){window.removeEventListener('resize',state.messageVirtual.scrollHandler);state.messageVirtual.scrollHandler=null;}}
async function render(){
  cleanupMessageVirtualization();
  $('#page-title').textContent=titles[state.view]||'HUB Bot';content.innerHTML='<div class="card empty">Carregando…</div>';
  const fn={dashboard:renderDashboard,messages:renderMessages,diagnostics:renderDiagnostics,calculators:renderCalculators,groups:renderGroups,analytics:renderAnalytics,settings:renderSettings,logs:renderLogs}[state.view];
  try{await fn();}catch(error){content.innerHTML=`<div class="card"><h3>Não foi possível carregar esta área</h3><p class="form-error">${esc(error.message)}</p></div>`;}
}

function selectedDashboardCards(){const raw=String(state.settings.dashboard_cards||'').split(',').map(x=>x.trim()).filter(Boolean);return raw.length?raw:DEFAULT_DASHBOARD_CARDS;}
async function renderDashboard(){state.dashboardRenderedAt=Date.now();
  const s=state.status||await api('/api/status');state.settings=await api('/api/settings');renderStatus();const stats=s.stats||{};const wa=s.whatsapp||{};const health=s.health||{};const cards=selectedDashboardCards();
  let diagnostics=[];if(cards.includes('errors'))diagnostics=await api('/api/diagnostics?limit=100');const errors=diagnostics.filter(x=>x.outcome==='error');
  const examples=stats.exampleCount?`<div class="example-banner"><div><h3>🧪 Modelos de demonstração ativos</h3><p>Você pode editar ou excluir esses modelos depois do primeiro teste.</p></div><button class="button danger" id="remove-examples">🗑️ Excluir modelos</button></div>`:'';
  const uncertainCount=Number(wa.persistentDeliveries?.uncertain||0);const pendingLate=Number(wa.pendingLateSendCount||0);
  const uncertainBanner=uncertainCount?`<div class="example-banner uncertain-banner"><div><h3>⚠️ ${uncertainCount} envio(s) precisam de revisão</h3><p>${pendingLate?`${pendingLate} ainda estão aguardando confirmação tardia do WhatsApp. `:''}Os demais não serão reenviados automaticamente para evitar mensagens duplicadas.</p></div><button class="button danger" id="review-uncertain">🔎 Revisar envios</button></div>`:'';
  const blocks=[];
  if(cards.includes('messages'))blocks.push(`<div class="grid stats">${statCard('Mensagens ativas',stats.messageCount||0)}${statCard('Inativas',stats.inactiveMessageCount||0)}${statCard('Arquivadas',stats.archivedMessageCount||0)}${statCard('Respostas hoje',stats.todayLogs||0)}</div>`);
  if(cards.includes('connection'))blocks.push(`<div class="card"><div class="toolbar"><div><h2>📱 Conexão do WhatsApp</h2><p class="muted">${esc(wa.message||'')}</p></div><div class="actions"><button class="button" id="restart-wa">🔄 Reiniciar</button><button class="button danger" id="logout-wa">🗑️ Remover sessão</button></div></div>${wa.qrDataUrl?`<div class="qr-box"><img src="${esc(wa.qrDataUrl)}" alt="QR code do WhatsApp"></div><p class="notice">📷 WhatsApp → Dispositivos conectados → Conectar um dispositivo.</p>`:`<div class="connection-line">${badge(wa.state||'desconhecido',wa.state==='ready'?'active':'warning')}<strong>${esc(wa.accountName||wa.accountNumber||'Conta ainda não conectada')}</strong></div>${wa.lastError?`<p class="form-error">⚠️ ${esc(wa.lastError)}</p>`:''}`}${wa.state==='ready'?`<p class="notice">✅ ${Number(wa.syncedGroupCount||0)} grupo(s) sincronizado(s) automaticamente.</p>`:''}</div>`);
  if(cards.includes('queue')){const guard=health.engine?.outboundGuard||{};blocks.push(`<div class="card"><h2>📤 Filas por conversa</h2><div class="health-grid"><div class="health-item"><small>Conversas ativas</small><strong>${Number(wa.activeConversationCount||0)}</strong></div><div class="health-item"><small>Mensagens aguardando</small><strong>${Number(wa.conversationQueueDepth||0)}</strong></div><div class="health-item"><small>Conversas acompanhadas</small><strong>${Number(wa.trackedConversationCount||0)}</strong></div><div class="health-item"><small>Bloqueadas pelo WhatsApp</small><strong>${Number(guard.blockedCount||0)}</strong></div></div><p class="muted">A ordem é preservada dentro de cada conversa; grupos e privados diferentes são processados em paralelo.</p></div>`);}
  if(cards.includes('last_reply'))blocks.push(`<div class="card"><h2>💬 Atividade recente</h2><div class="status-stack"><div class="status-row"><span>Última mensagem recebida</span><strong>${esc(fmtDate(health.engine?.lastMessageAt))}</strong></div><div class="status-row"><span>Última resposta enviada</span><strong>${esc(fmtDate(health.engine?.lastReplyAt))}</strong></div><div class="status-row"><span>Respostas desde o início</span><strong>${Number(health.engine?.totalReplies||0)}</strong></div></div></div>`);
  if(cards.includes('top_rules')){const top=(s.analytics?.top||[]).slice(0,6);blocks.push(`<div class="card"><h2>📈 Regras mais usadas — 30 dias</h2>${top.length?`<div class="topic-list">${top.map(x=>`<div><span>${esc(x.topic)}</span><strong>${Number(x.count)}</strong></div>`).join('')}</div>`:'<p class="muted">Ainda não há uso registrado.</p>'}</div>`);}
  if(cards.includes('errors'))blocks.push(`<div class="card"><h2>🚨 Erros recentes</h2>${errors.length?`<div class="stack compact">${errors.slice(-5).reverse().map(x=>`<div class="status-row"><span>${esc(x.summary||'Erro')}</span><small>${relativeTime(x.createdAt)}</small></div>`).join('')}</div>`:'<p class="notice">✅ Nenhum erro entre os diagnósticos mantidos em memória.</p>'}</div>`);
  if(cards.includes('memory')){const perf=health.engine?.performance?.series||{};const trigger=perf.trigger_evaluation_ms||{};const handle=perf.message_handle_ms||{};const send=perf.reply_send_ms||{};blocks.push(`<div class="card"><h2>🧠 Recursos e latência</h2><div class="health-grid"><div class="health-item"><small>Memória</small><strong>${fmtBytes(health.process?.rssBytes)}</strong></div><div class="health-item"><small>Heap usado</small><strong>${fmtBytes(health.process?.heapUsedBytes)}</strong></div><div class="health-item"><small>Tempo ativo</small><strong>${fmtDuration(health.process?.uptimeSeconds)}</strong></div><div class="health-item"><small>Banco</small><strong>${health.database?.ok?'✅ Íntegro':'⚠️ Verificar'}</strong></div><div class="health-item"><small>Gatilho p95</small><strong>${Number(trigger.p95||0).toFixed(1)} ms</strong></div><div class="health-item"><small>Processamento p95</small><strong>${Number(handle.p95||0).toFixed(1)} ms</strong></div><div class="health-item"><small>Envio p95</small><strong>${Number(send.p95||0).toFixed(1)} ms</strong></div><div class="health-item"><small>Event loop p99</small><strong>${Number(wa.watchdog?.latest?.eventLoopP99Ms||0).toFixed(1)} ms</strong></div></div><div class="actions top-gap"><button class="button small" id="checkpoint-wal">Otimizar banco agora</button></div></div>`);}
  content.innerHTML=`${uncertainBanner}${examples}<div class="dashboard-layout">${blocks.join('')}</div>`;
  if($('#review-uncertain'))$('#review-uncertain').onclick=reviewUncertainDeliveries;
  if($('#restart-wa'))$('#restart-wa').onclick=async()=>{await api('/api/whatsapp/restart',{method:'POST',body:'{}'});toast('🔄 Reinicialização iniciada.');};
  if($('#logout-wa'))$('#logout-wa').onclick=async()=>{if(!confirm('Remover a sessão e gerar um novo QR code?'))return;await api('/api/whatsapp/logout',{method:'POST',body:'{}'});toast('🗑️ Sessão removida.');};
  if($('#remove-examples'))$('#remove-examples').onclick=async()=>{if(!confirm('Excluir apenas os modelos de demonstração?'))return;await api('/api/examples',{method:'DELETE'});toast('🗑️ Modelos excluídos.');await loadAll();};
  if($('#checkpoint-wal'))$('#checkpoint-wal').onclick=async()=>{const result=await api('/api/database/checkpoint',{method:'POST',body:'{}'});toast(result.error?`Falha: ${result.error}`:`Banco otimizado (${result.mode||'checkpoint'}).`,Boolean(result.error));await refreshStatus();};
}


async function reviewUncertainDeliveries(){
  const payload=await api('/api/outbound/uncertain?limit=100');const items=payload.items||[];
  if(!items.length){toast('✅ Não há envios pendentes de revisão.');await refreshStatus();if(state.view==='dashboard')await renderDashboard();return;}
  const body=`<div class="notice"><strong>Evite duplicatas</strong><p>Um resultado desconhecido significa que o WhatsApp pode ter aceitado a mensagem sem devolver a confirmação ao bot. Reenvie somente depois de conferir a conversa.</p></div><div class="conflict-list uncertain-list">${items.map(item=>{const text=item.content?.content?.text||item.content?.metadata?.kind||'Mensagem ou anexo';return`<article class="conflict-item"><div class="toolbar"><div><span class="badge warning">Entrega #${Number(item.id)}</span><h3>${esc(item.conversation_id||'Conversa')}</h3></div><small>${fmtDate(item.updated_at)}</small></div><p class="message-snippet">${esc(String(text).slice(0,500))}</p><p class="muted">Tentativas: ${Number(item.attempts||0)}${item.last_error?` · ${esc(item.last_error)}`:''}</p><div class="actions">${item.reconciling?'<button class="button small" disabled>⏳ Reconciliação em andamento</button>':`<button class="button small danger retry-uncertain" data-id="${Number(item.id)}">↻ Reenviar manualmente</button>`}</div></article>`;}).join('')}</div>`;
  openInfoModal('Envios com resultado desconhecido',body);
  $$('.retry-uncertain').forEach(button=>button.onclick=async()=>{
    const id=Number(button.dataset.id);if(!confirm(`Reenviar a entrega #${id}?\n\nFaça isso somente após conferir que ela não chegou ao WhatsApp. O reenvio pode produzir uma mensagem duplicada.`))return;
    button.disabled=true;button.textContent='⏳ Preparando reenvio…';
    try{await api(`/api/outbound/${id}/retry`,{method:'POST',body:'{}'});toast(`↻ Entrega #${id} recolocada na fila.`);closeModal();await refreshStatus();if(state.view==='dashboard')await renderDashboard();}
    catch(error){button.disabled=false;button.textContent='↻ Reenviar manualmente';toast(error.message,true);}
  });
}

function effective(item){return item.draft||item;}
function scopeLabel(scope){return scope==='group'?'👥 Somente grupos':scope==='private'?'👤 Somente privado':'🌐 Grupos e privado';}
function statusLabel(item){const e=effective(item);return e.archived?'Arquivada':e.active&&item.published?'Ativa':'Inativa';}
function statusKind(item){const e=effective(item);return e.archived?'archived':e.active&&item.published?'active':'inactive';}
function triggerSummary(trigger={},counts={}){
  const sentences=(trigger.sentences||[]).map(v=>`<span class="tag sentence-tag">💬 ${esc(v)}</span>`);
  const keywords=(trigger.keywords||[]).map(v=>`<span class="tag keyword-tag">🔑 ${esc(v)}</span>`);
  const regex=trigger.regex_pattern?[`<span class="tag">🧩 Regex configurada</span>`]:[];
  const shown=[...sentences,...keywords,...regex];
  const total=Number(counts.sentences||sentences.length)+Number(counts.keywords||keywords.length)+Number(counts.required_words||0)+Number(counts.exact_phrases||0)+(trigger.regex_pattern?1:0);
  const extra=Math.max(0,total-shown.length);
  if(extra)shown.push(`<span class="tag muted-tag">+${extra} gatilho${extra===1?'':'s'}</span>`);
  return shown.length?shown.join(''):'<span class="muted">Sem gatilhos</span>';
}
function messageSnippet(text='',truncated=false){const value=String(text||'').trim();return value?`<p class="message-snippet">${esc(value).replace(/\n/g,'<br>')}${truncated?'…':''}</p>`:'<p class="muted">Sem prévia.</p>'; }
function sourceLabel(item){return item.source_type==='hub_package'?'Pacote do HUB':item.source_type==='teacher_import'?'Importação docente':'Criada no painel';}
function sourceBadge(item){const kind=item.source_type==='hub_package'?'package':item.source_type==='teacher_import'?'imported':'custom';const icon=item.source_type==='hub_package'?'📦':item.source_type==='teacher_import'?'📥':'✍️';return`${badge(`${icon} ${sourceLabel(item)}`,kind)}${item.source_type==='hub_package'?badge(item.customized?'Personalizada':'Padrão',item.customized?'warning':'active'):''}${item.has_package_update?badge('⬆️ Atualização disponível','warning'):''}`;}
// A virtualização atual usa windowing por scroll; substitui o antigo IntersectionObserver.
// Compatibilidade estrutural: id="messages-box" class="messages-grid top-gap"
const MESSAGE_SUMMARY_API='/api/messages?summary=1';
function applyMessageLayout(){const box=$('#messages-box');const viewport=$('#messages-viewport');if(!box)return;box.className=`messages-grid top-gap virtualized-message-grid view-${state.messageViewMode} columns-${state.messageColumns}`;if(viewport)viewport.className=`messages-viewport view-${state.messageViewMode}`;const columns=$('#message-columns');if(columns)columns.disabled=state.messageViewMode==='list';}

function tagOptions(selected=''){const tags=[...new Set(state.messages.flatMap(item=>effective(item).tags||[]))].sort((a,b)=>a.localeCompare(b));return`<option value="">Todas as etiquetas</option>${tags.map(tag=>`<option value="${esc(tag)}" ${tag===selected?'selected':''}>#${esc(tag)}</option>`).join('')}`;}
function parseSearchQuery(query){const tokens=String(query||'').match(/"[^"]+"|\S+/g)||[];const result={tags:[],status:'',scope:'',attachment:'',text:[]};for(let token of tokens){token=token.replace(/^"|"$/g,'');const low=normalizeSearch(token);if(low.startsWith('#'))result.tags.push(low.slice(1));else if(low.startsWith('status:'))result.status=low.split(':')[1];else if(['ativo','active'].includes(low))result.status='active';else if(['inativo','inactive'].includes(low))result.status='inactive';else if(['arquivado','arquivada','archived'].includes(low))result.status='archived';else if(low.startsWith('anexo:')||low.startsWith('attachment:'))result.attachment=low.split(':')[1];else if(low.startsWith('escopo:')||low.startsWith('scope:'))result.scope=low.split(':')[1];else if(['privado','private'].includes(low))result.scope='private';else if(['grupo','group'].includes(low))result.scope='group';else result.text.push(low);}return result;}
function attachmentMatches(attachment,filter){if(!filter)return true;if(!attachment)return false;const name=String(attachment.file_name||'').toLowerCase();const mime=String(attachment.mime_type||'').toLowerCase();return name.endsWith(`.${filter}`)||mime.includes(filter)||String(attachment.kind||'').toLowerCase()===filter;}
function messageMatches(item,query,selectedTag,statusFilter){const e=effective(item);const parsed=parseSearchQuery(query);const tags=e.tags||[];const status=e.archived?'archived':e.active?'active':'inactive';const haystack=String(e.search_text||`${e.title} ${tags.map(t=>`#${t}`).join(' ')} ${e.response_text||''}`).toLowerCase();if(parsed.text.some(term=>!haystack.includes(term)))return false;if(parsed.tags.some(tag=>!tags.includes(tag)))return false;if(selectedTag&&!tags.includes(selectedTag))return false;if(statusFilter==='current'&&e.archived)return false;if(statusFilter&&statusFilter!=='all'&&statusFilter!=='current'&&status!==statusFilter)return false;if(parsed.status&&status!==parsed.status)return false;const normalizedScope=parsed.scope==='privado'?'private':parsed.scope==='grupo'?'group':parsed.scope;if(normalizedScope&&e.scope!==normalizedScope&&e.scope!=='both')return false;if(!attachmentMatches(e.attachment||item.attachment,parsed.attachment))return false;return true;}

function messageConflicts(messageId){const id=Number(messageId);return (state.conflicts?.conflicts||[]).filter(conflict=>(conflict.items||[]).map(Number).includes(id));}
function conflictCount(messageId){return messageConflicts(messageId).length;}
function conflictingMessageIds(){const ids=new Set();for(const conflict of state.conflicts?.conflicts||[])for(const id of conflict.items||[])ids.add(Number(id));return ids;}
function conflictTitle(conflict){return (conflict.titles||[]).map(title=>String(title||'Mensagem sem nome')).join(' × ');}
function conflictDetailsHtml(conflict){const details=conflict.details||[];return details.length?`<div class="conflict-terms">${details.map(detail=>`<code>${esc(detail)}</code>`).join('')}</div>`:'<p class="muted">O relatório não informou o trecho exato.</p>';}
async function editMessageById(id){try{closeModal();messageModal(await api(`/api/messages/${Number(id)}`));}catch(error){toast(error.message,true);}}
function openConflictModal(messageId=null){
  const id=messageId===null?null:Number(messageId);const conflicts=id===null?(state.conflicts?.conflicts||[]):messageConflicts(id);
  if(!conflicts.length){openInfoModal('Conflitos de gatilho','<div class="notice">✅ Nenhum conflito encontrado para esta mensagem.</div>');return;}
  const body=`<div class="conflict-modal-intro"><p>${id===null?`Foram encontrados <strong>${conflicts.length}</strong> conflito(s).`:`Esta mensagem participa de <strong>${conflicts.length}</strong> conflito(s).`}</p><p class="muted">Cada item abaixo mostra os cartões envolvidos e os gatilhos sobrepostos. Use os botões para abrir diretamente o editor.</p></div><div class="conflict-list">${conflicts.map((conflict,index)=>`<article class="conflict-item ${conflict.severity==='danger'?'danger':''}"><div class="toolbar"><div><span class="badge warning">Conflito ${index+1}</span><h3>${esc(conflictTitle(conflict))}</h3></div></div>${conflictDetailsHtml(conflict)}<div class="actions">${(conflict.items||[]).map((itemId,itemIndex)=>`<button type="button" class="button small open-conflict-message" data-id="${Number(itemId)}">✏️ Abrir ${esc((conflict.titles||[])[itemIndex]||`mensagem ${itemId}`)}</button>`).join('')}</div></article>`).join('')}</div>`;
  openInfoModal(id===null?'Conflitos de gatilho':'Conflitos desta mensagem',body);
  $$('.open-conflict-message').forEach(button=>button.onclick=()=>editMessageById(button.dataset.id));
}
function renderConflictBanner(){
  const box=$('#message-conflicts');if(!box)return;const count=Number(state.conflicts?.count||0);box.hidden=!count;
  if(!count){box.innerHTML='';return;}
  const involved=conflictingMessageIds().size;
  box.innerHTML=`<div class="conflict-banner-copy"><strong>⚠️ Há ${count} conflito(s) de gatilho em ${involved} cartão(ões).</strong><span>Veja os gatilhos sobrepostos e abra diretamente os cartões envolvidos.</span></div><div class="actions"><button type="button" class="button small" id="open-conflicts">🔎 Ver conflitos</button><button type="button" class="button small ${state.conflictOnly?'primary':''}" id="toggle-conflict-filter">${state.conflictOnly?'📋 Mostrar todos':'⚠️ Mostrar envolvidos'}</button></div>`;
  $('#open-conflicts').onclick=()=>openConflictModal();
  $('#toggle-conflict-filter').onclick=async()=>{state.conflictOnly=!state.conflictOnly;renderConflictBanner();await reloadMessagePages();};
}

function messageServerRequest(cursor=''){
  const raw=$('#message-search')?.value||'';const parsed=parseSearchQuery(raw);const explicitTag=$('#tag-filter')?.value||'';const explicitStatus=$('#status-filter')?.value||'current';
  const status=parsed.status||explicitStatus;const tag=explicitTag||parsed.tags[0]||'';const params=new URLSearchParams({summary:'1',paginated:'1',limit:String(state.messagePage.limit),status,q:parsed.text.join(' ')});
  if(cursor)params.set('cursor',cursor);if(tag)params.set('tag',tag);if(state.conflictOnly)params.set('conflicts','1');return `${MESSAGE_SUMMARY_API}&${params.toString()}`;
}
async function loadMessagePage({reset=false}={}){
  if(state.messagePage.loading)return;
  if(!reset&&!state.messagePage.nextCursor)return;
  state.messagePage.loading=true;updateMessagePageStatus();
  try{
    const cursor=reset?'':state.messagePage.nextCursor;const result=await api(messageServerRequest(cursor),{timeoutMs:10000});
    const items=Array.isArray(result)?result:(result.items||[]);
    state.messages=reset?items:[...state.messages,...items.filter(item=>!state.messages.some(current=>Number(current.id)===Number(item.id)))];
    state.messagePage.total=Number(result.total??state.messages.length);state.messagePage.nextCursor=String(result.nextCursor||'');
    const tagFilter=$('#tag-filter');if(tagFilter){const selected=tagFilter.value;tagFilter.innerHTML=tagOptions(selected);if([...tagFilter.options].some(option=>option.value===selected))tagFilter.value=selected;}
    if(reset){const viewport=$('#messages-viewport');if(viewport)viewport.scrollTop=0;state.messageVirtual.start=0;}
    drawMessages();
  }finally{state.messagePage.loading=false;updateMessagePageStatus();}
}
async function reloadMessagePages(){state.messages=[];state.selectedMessages.clear();state.messagePage={...state.messagePage,total:0,nextCursor:'',loading:false,queryKey:''};await loadMessagePage({reset:true});}
function updateMessagePageStatus(){const box=$('#messages-more');if(!box)return;const loaded=state.messages.length,total=state.messagePage.total;box.innerHTML=state.messagePage.loading?`<span class="spinner-dot"></span> Carregando…`:state.messagePage.nextCursor?`Carregar mais: ${loaded} de ${total} mensagens carregadas · role para continuar`:`${total} mensagem${total===1?'':'s'} encontrada${total===1?'':'s'}.`;}
function virtualColumnCount(){if(state.messageViewMode==='list')return 1;const explicit=Number(state.messageColumns);if(Number.isFinite(explicit)&&explicit>=1)return explicit;const width=$('#messages-viewport')?.clientWidth||1000;return Math.max(1,Math.min(4,Math.floor((width+16)/390)));}
function messageRowHeight(){return state.messageViewMode==='list'?250:390;}
function visibleMessages(){const q=$('#message-search')?.value||'';const tag=$('#tag-filter')?.value||'';const status=$('#status-filter')?.value||'current';const involved=state.conflictOnly?conflictingMessageIds():null;return state.messages.filter(item=>(!involved||involved.has(Number(item.id)))&&messageMatches(item,q,tag,status));}
function virtualSlice(items){const viewport=$('#messages-viewport');const columns=virtualColumnCount();const rowHeight=messageRowHeight();const overscan=state.messageVirtual.overscanRows;const scrollTop=viewport?.scrollTop||0;const viewportHeight=viewport?.clientHeight||700;const startRow=Math.max(0,Math.floor(scrollTop/rowHeight)-overscan);const endRow=Math.min(Math.ceil(items.length/columns),Math.ceil((scrollTop+viewportHeight)/rowHeight)+overscan);const start=startRow*columns;const end=Math.min(items.length,endRow*columns);state.messageVirtual={...state.messageVirtual,start,end,rowHeight};return{items:items.slice(start,end),start,end,columns,topHeight:startRow*rowHeight,bottomHeight:Math.max(0,(Math.ceil(items.length/columns)-endRow)*rowHeight)};}
function bindMessageViewport(){const viewport=$('#messages-viewport');if(!viewport)return;let scheduled=false;const onScroll=()=>{if(scheduled)return;scheduled=true;requestAnimationFrame(()=>{scheduled=false;drawMessages();});};viewport.addEventListener('scroll',onScroll,{passive:true});state.messageVirtual.scrollHandler=onScroll;window.addEventListener('resize',onScroll,{passive:true});}

function teacherScheduleLines(item){return(item.schedule||[]).map(entry=>entry.description||[entry.discipline,entry.semester,entry.day,entry.hours].filter(Boolean).join(' — ')).filter(Boolean).join('\n');}
async function openTeacherDirectory(){
  const teachers=await api('/api/teachers');
  const rows=teachers.map(item=>`<tr><td><strong>${esc(item.name)}</strong><br><small>${esc(item.email)}</small></td><td>${item.room?`${esc(item.room)}${item.building?` · ${esc(item.building)}`:''}`:'<span class="muted">Não confirmada</span>'}</td><td>${item.room_confirmed_at?esc(item.room_confirmed_at.split('-').reverse().join('/')):'—'}</td><td><div class="actions"><button type="button" class="button small edit-teacher" data-id="${Number(item.id)}">✏️ Editar</button><button type="button" class="button small danger delete-teacher" data-id="${Number(item.id)}">🗑️</button></div></td></tr>`).join('');
  openInfoModal('Cadastro estruturado de professores',`<div class="toolbar"><div><p class="muted">A localização só é enviada quando sala, data e fonte de confirmação estiverem preenchidas.</p></div><button type="button" class="button primary" id="add-teacher-profile">➕ Professor</button></div><div class="table-wrap"><table><thead><tr><th>Professor</th><th>Sala / bloco</th><th>Confirmação</th><th>Ações</th></tr></thead><tbody>${rows||'<tr><td colspan="4" class="muted">Nenhum professor cadastrado.</td></tr>'}</tbody></table></div>`);
  $('#add-teacher-profile').onclick=()=>{closeModal();teacherProfileModal(null);};
  $$('.edit-teacher').forEach(button=>button.onclick=()=>{const teacher=teachers.find(item=>Number(item.id)===Number(button.dataset.id));closeModal();teacherProfileModal(teacher);});
  $$('.delete-teacher').forEach(button=>button.onclick=async()=>{if(!confirm('Excluir este professor do cadastro estruturado?'))return;await api(`/api/teachers/${button.dataset.id}`,{method:'DELETE'});toast('🗑️ Professor excluído.');closeModal();await openTeacherDirectory();});
}
function teacherProfileModal(item){
  const schedule=teacherScheduleLines(item||{});const disciplines=(item?.disciplines||[]).join('\n');
  const body=`<div class="form-grid"><label class="full">Nome completo<input name="name" value="${esc(item?.name||'')}" required></label><label>E-mail institucional<input name="email" type="email" value="${esc(item?.email||'')}" required></label><label>Período acadêmico<input name="academic_period" value="${esc(item?.academic_period||'')}" placeholder="2026.2"></label><label class="full">Aliases — um por linha<textarea name="aliases">${esc((item?.aliases||[]).join('\n'))}</textarea></label><label>Sala de atendimento<input name="room" value="${esc(item?.room||'')}" placeholder="Ex.: H410"></label><label>Bloco / prédio<input name="building" value="${esc(item?.building||'')}" placeholder="Ex.: Bloco H"></label><label>Data da confirmação<input name="room_confirmed_at" type="date" value="${esc(item?.room_confirmed_at||'')}"></label><label>Fonte da confirmação<input name="room_source" value="${esc(item?.room_source||'')}" placeholder="Ex.: Coordenação de BSI"></label><label class="full">Disciplinas — uma por linha<textarea name="disciplines">${esc(disciplines)}</textarea></label><label class="full">Dias e horários — uma linha por item<textarea name="schedule">${esc(schedule)}</textarea></label><label class="full">Observações internas<textarea name="notes">${esc(item?.notes||'')}</textarea></label><label class="check"><input name="active" type="checkbox" ${item?.active!==false?'checked':''}> Professor ativo</label></div><div class="notice top-gap">A sala só será informada pelo bot quando também houver data e fonte de confirmação. Se esses dados estiverem vazios, o bot encaminhará para o docente e para a Coordenação de BSI.</div>`;
  openModal(item?'Editar professor':'Novo professor',body,async form=>{const data=Object.fromEntries(new FormData(form).entries());data.aliases=form.aliases.value;data.disciplines=form.disciplines.value;data.schedule=form.schedule.value;data.active=form.active.checked;await api(item?`/api/teachers/${item.id}`:'/api/teachers',{method:item?'PUT':'POST',body:JSON.stringify(data)});toast('✅ Cadastro docente salvo.');closeModal();await openTeacherDirectory();},{wide:true,saveLabel:'💾 Salvar professor'});
}

async function openSectorDirectory(){
  const sectors=await api('/api/sectors');state.sectors=sectors;
  const rows=sectors.map(item=>`<tr><td><strong>${esc(item.acronym||item.name)}</strong><br><small>${esc(item.name)}</small></td><td>${item.email?esc(item.email):'<span class="muted">Não cadastrado</span>'}</td><td>${item.location?esc(item.location):'<span class="muted">Não confirmada</span>'}</td><td>${item.verified_at?esc(item.verified_at.split('-').reverse().join('/')):'—'}</td><td><div class="actions"><button type="button" class="button small edit-sector" data-id="${Number(item.id)}">✏️ Editar</button><button type="button" class="button small danger delete-sector" data-id="${Number(item.id)}">🗑️</button></div></td></tr>`).join('');
  openInfoModal('Cadastro estruturado de setores',`<div class="toolbar"><div><p class="muted">Contatos, localização, serviços e fonte são mantidos em um único cadastro. O bot reconhece a intenção e o setor sem dezenas de frases duplicadas.</p></div><button type="button" class="button primary" id="add-sector-profile">➕ Setor</button></div><div class="table-wrap"><table><thead><tr><th>Setor</th><th>E-mail</th><th>Localização</th><th>Verificação</th><th>Ações</th></tr></thead><tbody>${rows||'<tr><td colspan="5" class="muted">Nenhum setor cadastrado.</td></tr>'}</tbody></table></div>`);
  $('#add-sector-profile').onclick=()=>{closeModal();sectorProfileModal(null);};
  $$('.edit-sector').forEach(button=>button.onclick=()=>{const sector=sectors.find(item=>Number(item.id)===Number(button.dataset.id));closeModal();sectorProfileModal(sector);});
  $$('.delete-sector').forEach(button=>button.onclick=async()=>{if(!confirm('Excluir este setor do cadastro estruturado?'))return;await api(`/api/sectors/${button.dataset.id}`,{method:'DELETE'});toast('🗑️ Setor excluído.');closeModal();await openSectorDirectory();});
}
function sectorProfileModal(item){
  const body=`<div class="form-grid"><label>Sigla ou nome curto<input name="acronym" value="${esc(item?.acronym||'')}" required placeholder="Ex.: CAENS"></label><label>Nome completo<input name="name" value="${esc(item?.name||'')}" required></label><label class="full">Aliases — um por linha<textarea name="aliases">${esc((item?.aliases||[]).join('\n'))}</textarea></label><label>E-mail<input name="email" type="email" value="${esc(item?.email||'')}"></label><label>WhatsApp ou link wa.me<input name="whatsapp" value="${esc(item?.whatsapp||'')}"></label><label>Telefone / ramal<input name="phone" value="${esc(item?.phone||'')}"></label><label>Localização<input name="location" value="${esc(item?.location||'')}"></label><label class="full">Serviços oferecidos — um por linha<textarea name="services">${esc((item?.services||[]).join('\n'))}</textarea></label><label class="full">URL da fonte oficial<input name="source_url" type="url" value="${esc(item?.source_url||'')}"></label><label>Título da fonte<input name="source_title" value="${esc(item?.source_title||'')}"></label><label>Data da verificação<input name="verified_at" type="date" value="${esc(item?.verified_at||'')}"></label><label class="check"><input name="active" type="checkbox" ${item?.active!==false?'checked':''}> Setor ativo</label></div>`;
  openModal(item?'Editar setor':'Novo setor',body,async form=>{const data=Object.fromEntries(new FormData(form).entries());data.aliases=form.aliases.value;data.services=form.services.value;data.active=form.active.checked;await api(item?`/api/sectors/${item.id}`:'/api/sectors',{method:item?'PUT':'POST',body:JSON.stringify(data)});toast('✅ Cadastro do setor salvo.');closeModal();await openSectorDirectory();},{wide:true,saveLabel:'💾 Salvar setor'});
}

async function renderMessages(){
  const token=++state.messageLoadToken;state.selectedMessages.clear();state.messages=[];state.messagePage={total:0,nextCursor:'',loading:false,queryKey:'',limit:60};
  content.innerHTML=`<div class="toolbar"><div><h2>💬 Mensagens automáticas</h2><p class="muted">Carregando a primeira página…</p></div></div><div class="messages-grid top-gap">${Array.from({length:6},()=>'<div class="card message-skeleton"><span></span><span></span><span></span></div>').join('')}</div>`;
  const synonyms=await api('/api/synonyms');if(token!==state.messageLoadToken||state.view!=='messages')return;state.synonyms=synonyms;state.conflicts={count:0,conflicts:[],loading:true};state.conflictOnly=false;
  content.innerHTML=`<div class="toolbar messages-toolbar"><div class="filter-row"><input id="message-search" class="search" placeholder="#contato ativo · anexo:pdf · status:inativo · privado"><select id="tag-filter">${tagOptions()}</select><select id="status-filter"><option value="current">Ativas e inativas</option><option value="active">Somente ativas</option><option value="inactive">Somente inativas</option><option value="archived">Somente arquivadas</option><option value="all">Tudo</option></select></div><div class="actions"><button class="button" id="manage-synonyms">🔤 Sinônimos</button><button class="button" id="manage-teachers">👨‍🏫 Cadastro docente</button><button class="button" id="manage-sectors">🏢 Cadastro de setores</button><button class="button" id="import-professor-schedule">📥 Atualizar quadro docente</button><button class="button" id="import-messages">📄 Importar mensagens</button><button class="button primary" id="add-message">➕ Nova mensagem</button></div></div>
  <div class="view-toolbar card"><div><strong>Visualização</strong><small>Paginação no servidor e virtualização mantêm no navegador apenas os cartões visíveis.</small></div><label>Modo<select id="message-view"><option value="cards" ${state.messageViewMode==='cards'?'selected':''}>Cards</option><option value="list" ${state.messageViewMode==='list'?'selected':''}>Lista</option></select></label><label>Colunas<select id="message-columns"><option value="auto" ${state.messageColumns==='auto'?'selected':''}>Dinâmicas</option>${[1,2,3,4].map(value=>`<option value="${value}" ${state.messageColumns===String(value)?'selected':''}>${value}</option>`).join('')}</select></label></div>
  <div id="bulk-bar" class="bulk-bar" hidden><strong id="bulk-count">0 selecionadas</strong><button class="button small" data-bulk="activate">✅ Ativar</button><button class="button small" data-bulk="deactivate">⏸️ Desativar</button><button class="button small" data-bulk="archive">📦 Arquivar</button><button class="button small" data-bulk="unarchive">📤 Desarquivar</button><button class="button small" data-bulk="add-tag">#️⃣ Etiqueta</button><button class="button small" data-bulk="export">⬇️ Exportar</button><button class="button small danger" data-bulk="delete">🗑️ Excluir</button></div>
  <div id="message-conflicts" class="notice warn conflict-banner" hidden></div><p class="muted order-help">A ordenação por arrastar fica disponível quando toda a consulta estiver em uma única página.</p><div id="messages-viewport" class="messages-viewport"><div id="messages-box" class="messages-grid top-gap virtualized-message-grid"></div></div><div id="messages-more" class="load-more-wrap"></div>`;
  applyMessageLayout();bindMessageViewport();
  let filterTimer;const scheduleReload=()=>{clearTimeout(filterTimer);filterTimer=setTimeout(()=>reloadMessagePages().catch(error=>toast(error.message,true)),180);};
  $('#message-search').oninput=scheduleReload;$('#tag-filter').onchange=scheduleReload;$('#status-filter').onchange=scheduleReload;
  $('#message-view').onchange=event=>{state.messageViewMode=event.target.value;localStorage.setItem('hub-message-view',state.messageViewMode);applyMessageLayout();drawMessages();};
  $('#message-columns').onchange=event=>{state.messageColumns=event.target.value;localStorage.setItem('hub-message-columns',state.messageColumns);applyMessageLayout();drawMessages();};
  $('#add-message').onclick=()=>messageModal();$('#import-messages').onclick=messageCsvModal;$('#import-professor-schedule').onclick=professorScheduleImportModal;$('#manage-synonyms').onclick=openSynonymManager;$('#manage-teachers').onclick=openTeacherDirectory;$('#manage-sectors').onclick=openSectorDirectory;
  $$('#bulk-bar [data-bulk]').forEach(btn=>btn.onclick=()=>runBulkAction(btn.dataset.bulk));
  await loadMessagePage({reset:true});
  const defer=window.requestIdleCallback||((fn)=>setTimeout(fn,50));defer(async()=>{try{const report=await api('/api/conflicts',{timeoutMs:120000});if(token!==state.messageLoadToken||state.view!=='messages')return;state.conflicts=report;renderConflictBanner();drawMessages();}catch{}});
}
function drawMessages(){
  const allItems=visibleMessages();const box=$('#messages-box');if(!box)return;applyMessageLayout();
  if(!allItems.length){box.innerHTML='<div class="card empty">Nenhuma mensagem encontrada.</div>';updateMessagePageStatus();updateBulkBar();return;}
  const slice=virtualSlice(allItems);const unfiltered=!($('#message-search')?.value||'').trim()&&!($('#tag-filter')?.value||'')&&($('#status-filter')?.value||'current')==='current';
  const cardHtml=slice.items.map(item=>{const e=effective(item);const attachment=e.attachment||item.attachment;const conflicts=messageConflicts(item.id);const conflictBadge=conflicts.length?badge(`⚠️ ${conflicts.length} conflito${conflicts.length===1?'':'s'}`,'warning'):'';const conflictButton=conflicts.length?`<button class="button small warning-button view-message-conflicts" data-id="${item.id}">⚠️ Ver conflitos</button>`:'';const packageButton=item.has_package_update?`<button class="button small warning-button compare-package-update" data-id="${item.id}">⇄ Comparar atualização</button>`:'';return`<article class="card message-card ${e.archived?'archived':''} ${conflicts.length?'has-conflict':''}" data-id="${item.id}" draggable="${unfiltered&&!e.archived&&!state.conflictOnly&&!state.messagePage.nextCursor?'true':'false'}"><div class="message-select"><input class="select-message" type="checkbox" data-id="${item.id}" ${state.selectedMessages.has(item.id)?'checked':''}><span class="drag-handle" title="Arrastar para ordenar">⠿</span></div><div class="toolbar"><div><div class="tag-list">${item.is_example?badge('🧪 Exemplo','example'):''}${badge(statusLabel(item),statusKind(item))}${badge(scopeLabel(e.scope),'scope')}${sourceBadge(item)}${e.source_url?badge(`🔎 Fonte${e.verified_at?` · ${e.verified_at.split('-').reverse().join('/')}`:''}`,'scope'):''}${attachment?badge(`📎 ${attachment.file_name}`,'attachment'):''}${conflictBadge}</div><h3>${esc(e.title)}</h3>${(e.tags||[]).length?`<div class="tag-list">${e.tags.map(tag=>`<span class="tag hashtag">#${esc(tag)}</span>`).join('')}</div>`:'<p class="muted">Sem etiquetas</p>'}</div><div class="row-actions wrap">${packageButton}${conflictButton}<button class="button small edit-message" data-id="${item.id}">✏️ Editar</button><button class="button small duplicate-message" data-id="${item.id}">📄 Duplicar</button><button class="button small history-message" data-id="${item.id}">🕘 Histórico</button><button class="button small danger delete-message" data-id="${item.id}">🗑️ Excluir</button></div></div><div class="tag-list trigger-preview">${triggerSummary(e.trigger,item.trigger_counts||{})}</div>${messageSnippet(e.response_text,e.response_truncated)}${attachment?`<p class="attachment-line"><a href="/api/messages/${item.id}/attachment/download" target="_blank">📎 ${esc(attachment.file_name)}</a> · ${fmtBytes(attachment.size_bytes)}</p>`:''}</article>`;}).join('');
  box.innerHTML=`<div class="virtual-spacer top" style="height:${slice.topHeight}px"></div>${cardHtml}<div class="virtual-spacer bottom" style="height:${slice.bottomHeight}px"></div>`;
  box.querySelectorAll('.select-message').forEach(input=>input.onchange=()=>{const id=Number(input.dataset.id);if(input.checked)state.selectedMessages.add(id);else state.selectedMessages.delete(id);updateBulkBar();});
  box.querySelectorAll('.view-message-conflicts').forEach(btn=>btn.onclick=()=>openConflictModal(Number(btn.dataset.id)));box.querySelectorAll('.compare-package-update').forEach(btn=>btn.onclick=()=>openPackageUpdateModal(Number(btn.dataset.id)));
  box.querySelectorAll('.edit-message').forEach(btn=>btn.onclick=async()=>{try{messageModal(await api(`/api/messages/${btn.dataset.id}`));}catch(error){toast(error.message,true);}});
  box.querySelectorAll('.duplicate-message').forEach(btn=>btn.onclick=async()=>{const copy=await api(`/api/messages/${btn.dataset.id}/duplicate`,{method:'POST',body:'{}'});toast('📄 Cópia criada como inativa.');await renderMessages();messageModal(copy);});
  box.querySelectorAll('.history-message').forEach(btn=>btn.onclick=()=>historyModal(Number(btn.dataset.id)));box.querySelectorAll('.delete-message').forEach(btn=>btn.onclick=async()=>{if(!confirm('Excluir esta mensagem e seu histórico?'))return;await api(`/api/messages/${btn.dataset.id}`,{method:'DELETE'});toast('🗑️ Mensagem excluída.');await renderMessages();});
  setupDragOrdering(unfiltered&&!state.conflictOnly&&!state.messagePage.nextCursor);updateBulkBar();updateMessagePageStatus();
  if(state.messagePage.nextCursor&&slice.end>=allItems.length-Math.max(4,slice.columns*3))loadMessagePage().catch(error=>toast(error.message,true));
}
function setupDragOrdering(enabled){if(!enabled)return;let dragged=null;$$('#messages-box .message-card[draggable="true"]').forEach(card=>{card.ondragstart=e=>{dragged=card;card.classList.add('dragging');e.dataTransfer.effectAllowed='move';};card.ondragend=async()=>{card.classList.remove('dragging');dragged=null;const ids=$$('#messages-box .message-card').map(x=>Number(x.dataset.id));try{await api('/api/messages/reorder',{method:'POST',body:JSON.stringify({ids})});toast('↕️ Ordem salva.');await reloadMessagePages();}catch(error){toast(error.message,true);}};card.ondragover=e=>{e.preventDefault();if(!dragged||dragged===card)return;const rect=card.getBoundingClientRect();const before=e.clientY<rect.top+rect.height/2;card.parentNode.insertBefore(dragged,before?card:card.nextSibling);};});}
function updateBulkBar(){const bar=$('#bulk-bar');if(!bar)return;const count=state.selectedMessages.size;bar.hidden=!count;$('#bulk-count').textContent=`${count} selecionada${count===1?'':'s'}`;}
async function runBulkAction(action){const ids=[...state.selectedMessages];if(!ids.length)return;if(action==='export'){const payload=await api('/api/messages/export',{method:'POST',body:JSON.stringify({ids})});downloadBlob(`mensagens-selecionadas-${new Date().toISOString().slice(0,10)}.json`,JSON.stringify(payload,null,2));return;}let value='';if(action==='add-tag'){value=prompt('Etiqueta que será adicionada, por exemplo #contato:','');if(!value)return;}if(action==='delete'&&!confirm(`Excluir ${ids.length} mensagem(ns) e seus históricos?`))return;await api('/api/messages/bulk',{method:'POST',body:JSON.stringify({ids,action,value})});toast('✅ Ação em lote concluída.');await renderMessages();}
function synonymOptions(selected=[]){return state.synonyms.map(group=>`<option value="${group.id}" ${selected.includes(group.id)?'selected':''}>${esc(group.name)} — ${(group.terms||[]).map(esc).join(', ')}</option>`).join('');}
async function uploadMessageAttachment(messageId,file){if(!file)return null;if(file.size>25*1024*1024)throw new Error('O arquivo excede 25 MiB.');const response=await fetch(`/api/messages/${messageId}/attachment`,{method:'POST',credentials:'same-origin',headers:{'Content-Type':file.type||'application/octet-stream','X-File-Name':encodeURIComponent(file.name)},body:file});const payload=await response.json();if(!response.ok)throw new Error(payload.error||'Falha ao enviar o anexo.');return payload;}

function sampleVariables(text,context={}){const now=new Date();const values={data:new Intl.DateTimeFormat('pt-BR').format(now),hora:new Intl.DateTimeFormat('pt-BR',{hour:'2-digit',minute:'2-digit'}).format(now),nome_do_grupo:context.groupName||'Grupo de Sistemas de Informação',nome_da_pessoa:context.senderName||'Maria'};return String(text||'').replace(/\{\{\s*(data|hora|nome_do_grupo|nome_da_pessoa)\s*\}\}/gi,(_,key)=>values[key.toLowerCase()]);}
function renderWhatsAppMarkup(text,context={}){let value=esc(sampleVariables(text,context));const codeBlocks=[];value=value.replace(/```([\s\S]*?)```/g,(_,code)=>{const key=`@@CODE${codeBlocks.length}@@`;codeBlocks.push(`<pre class="wa-code">${code}</pre>`);return key;});value=value.replace(/`([^`\n]+)`/g,'<code>$1</code>');value=value.replace(/\*([^*\n]+)\*/g,'<strong>$1</strong>');value=value.replace(/_([^_\n]+)_/g,'<em>$1</em>');value=value.replace(/~([^~\n]+)~/g,'<del>$1</del>');value=value.replace(/(https?:\/\/[^\s<]+)/g,'<a href="$1" target="_blank" rel="noreferrer">$1</a>');value=value.replace(/\n/g,'<br>');codeBlocks.forEach((html,index)=>{value=value.replace(`@@CODE${index}@@`,html);});return value;}
function insertAtCursor(textarea,value){const start=textarea.selectionStart??textarea.value.length;const end=textarea.selectionEnd??start;textarea.value=textarea.value.slice(0,start)+value+textarea.value.slice(end);textarea.focus();textarea.selectionStart=textarea.selectionEnd=start+value.length;textarea.dispatchEvent(new Event('input',{bubbles:true}));}
function collectMessageForm(form,currentAttachment,item){const status=form.status.value;return{title:form.title.value,topic:'',tags:list(form.tags.value),scope:form.scope.value,response_text:form.response_text.value,details_text:form.details_text.value,source_url:form.source_url.value,source_title:form.source_title.value,verified_at:form.verified_at.value,priority:Number(form.priority.value||0),sort_order:Number(item?effective(item).sort_order||0:0),active:status==='active',archived:status==='archived',attachment:currentAttachment,trigger:{sentences:list(form.sentences.value),keywords:list(form.keywords.value),match_mode:'all',typo_tolerance:Number(form.typo_tolerance.value),exact_phrases:[],required_words:list(form.required_words.value),excluded_words:list(form.excluded_words.value),negative_examples:list(form.negative_examples.value),synonym_group_ids:[...form.synonym_group_ids.selectedOptions].map(o=>Number(o.value)),regex_pattern:form.regex_pattern.value,regex_flags:form.regex_flags.value,require_question_mark:form.require_question_mark.checked}};}
function validationHtml(report){if(!report)return'<span class="muted">A validação aparecerá enquanto você edita.</span>';const errors=report.errors||[];const warnings=report.warnings||[];if(!errors.length&&!warnings.length)return'<div class="notice">✅ Gatilhos válidos e sem conflitos óbvios.</div>';return`${errors.map(x=>`<div class="validation-item error">❌ ${esc(x)}</div>`).join('')}${warnings.map(x=>`<div class="validation-item warn">⚠️ ${esc(x)}</div>`).join('')}`;}
function messageModal(item=null){
  const e=item?effective(item):{title:'',tags:[],scope:'both',response_text:'',details_text:'',source_url:'',source_title:'',verified_at:'',priority:0,active:true,archived:false,attachment:null,trigger:{sentences:[],keywords:[],required_words:[],excluded_words:[],negative_examples:[],require_question_mark:true,typo_tolerance:0,regex_pattern:'',regex_flags:'iu',synonym_group_ids:[]}};const t=e.trigger||{};const currentAttachment=e.attachment||item?.attachment||null;
  const originInfo=item?`<div class="origin-editor-banner"><div><strong>Origem: ${esc(sourceLabel(item))}</strong><span>${item.source_type==='hub_package'?(item.customized?'Este cartão foi personalizado no painel. Atualizações do pacote não o substituirão sem confirmação.':'Este cartão ainda corresponde ao padrão do pacote.'):'Este conteúdo é administrado localmente.'}</span></div>${item.pending_package_update?`<button type="button" class="button small warning-button" id="compare-origin-update">⇄ Comparar atualização</button>`:''}</div>`:'';
  const body=`${originInfo}<div class="message-editor-layout"><div class="editor-pane"><div class="form-grid"><label class="full">Nome interno<input name="title" value="${esc(e.title)}" placeholder="Ex.: Contato de Bruno" required><small>Serve apenas para organizar o painel.</small></label><label class="full">Etiquetas com #<input name="tags" value="${esc((e.tags||[]).map(tag=>`#${tag}`).join(', '))}" placeholder="#contato, #faq, #documentos"></label><label>Onde pode responder<select name="scope"><option value="both" ${e.scope==='both'||!e.scope?'selected':''}>Grupos e privado</option><option value="group" ${e.scope==='group'?'selected':''}>Somente grupos</option><option value="private" ${e.scope==='private'?'selected':''}>Somente privado</option></select></label><label>Situação<select name="status"><option value="active" ${e.active&&!e.archived?'selected':''}>Ativa</option><option value="inactive" ${!e.active&&!e.archived?'selected':''}>Inativa</option><option value="archived" ${e.archived?'selected':''}>Arquivada</option></select></label><label class="trigger-channel">Sentenças ou trechos<textarea name="sentences" placeholder="Uma alternativa por linha">${esc((t.sentences||[]).join('\n'))}</textarea><small>Em mensagens maiores, uma delas deve aparecer e a mensagem precisa terminar com ?. Sem ?, somente uma forma direta completa cadastrada pode responder.</small></label><label class="trigger-channel">Palavras-chave obrigatórias<textarea name="keywords" placeholder="Uma por linha">${esc((t.keywords||[]).join('\n'))}</textarea><small>todas devem aparecer; a ordem não importa, ignorando capitalização e acentos.</small></label><label class="full">Resposta completa do bot — curta por padrão<textarea class="answer-area" name="response_text" required>${esc(e.response_text)}</textarea><small>Esta é a resposta principal enviada no WhatsApp.</small></label><label class="full">Mais detalhes — opcional<textarea class="answer-area" name="details_text">${esc(e.details_text||'')}</textarea><small>Depois dessa resposta, a pessoa pode escrever “mais detalhes” na mesma conversa.</small></label><label class="full">URL da fonte oficial<input name="source_url" type="url" value="${esc(e.source_url||'')}" placeholder="https://portal.ifba.edu.br/..."></label><label>Título da fonte<input name="source_title" value="${esc(e.source_title||'')}" placeholder="Página oficial do IFBA"></label><label>Verificada em<input name="verified_at" type="date" value="${esc(e.verified_at||'')}"></label><div class="variable-toolbar full"><span>Variáveis:</span>${['data','hora','nome_do_grupo','nome_da_pessoa'].map(v=>`<button type="button" class="button small insert-variable" data-value="{{${v}}}">{{${v}}}</button>`).join('')}</div><div class="attachment-editor full"><h3>📎 Anexo da mensagem (opcional)</h3>${currentAttachment?`<p>Atual: <a href="/api/messages/${item.id}/attachment/download" target="_blank">${esc(currentAttachment.file_name)}</a> · ${fmtBytes(currentAttachment.size_bytes)}</p><label class="check"><input name="remove_attachment" type="checkbox"> Remover o anexo atual</label>`:'<p class="muted">Nenhum anexo cadastrado.</p>'}<label>Escolher ${currentAttachment?'novo':'um'} arquivo<input name="attachment_file" type="file" accept="image/*,audio/*,.pdf,.doc,.docx,.xls,.xlsx,.ppt,.pptx,.odt,.ods,.odp,.txt,.csv,.zip"></label></div><details class="advanced-box full"><summary>⚙️ Condições avançadas</summary><div class="form-grid top-gap"><label>Prioridade legada<input name="priority" type="number" min="-100" max="100" value="${Number(e.priority||0)}"></label><label>Tolerância a erros<select name="typo_tolerance"><option value="0" ${Number(t.typo_tolerance||0)===0?'selected':''}>Nenhuma</option><option value="1" ${Number(t.typo_tolerance)===1?'selected':''}>1 caractere</option><option value="2" ${Number(t.typo_tolerance)===2?'selected':''}>2 caracteres</option></select></label><label>Termos obrigatórios extras<textarea name="required_words">${esc((t.required_words||[]).join('\n'))}</textarea></label><label>Termos que bloqueiam<textarea name="excluded_words">${esc((t.excluded_words||[]).join('\n'))}</textarea></label><label class="full">Exemplos que nunca devem responder<textarea name="negative_examples">${esc((t.negative_examples||[]).join('\n'))}</textarea></label><label class="full">Sinônimos reutilizáveis<select name="synonym_group_ids" multiple>${synonymOptions(t.synonym_group_ids||[])}</select></label><label>Expressão regular<input name="regex_pattern" value="${esc(t.regex_pattern||'')}"></label><label>Opções da regex<input name="regex_flags" value="${esc(t.regex_flags||'iu')}"></label><label class="check full"><input name="require_question_mark" type="checkbox" checked disabled> Proteção global: texto adicional exige ? no final; frase direta completa pode responder sem ?</label></div></details><div id="caption-meter" class="validation-box full"></div><div id="message-validation" class="validation-box full"></div></div></div><aside class="preview-pane"><div class="preview-head"><h3>📱 Prévia no WhatsApp</h3><small>Exibe formatação e variáveis com valores de exemplo.</small></div><div id="live-message-preview" class="wa-bubble"></div><div id="live-attachment-preview" class="preview-attachment" hidden></div></aside></div>`;
  openModal(item?'Editar mensagem automática':'Nova mensagem automática',body,async form=>{const data=collectMessageForm(form,currentAttachment,item);const report=await api('/api/messages/validate',{method:'POST',body:JSON.stringify({id:item?.id||null,message:data})});if(!report.valid)throw new Error((report.errors||[]).join(' '));if(report.warnings?.length&&!confirm(`A validação encontrou avisos:\n\n${report.warnings.join('\n')}\n\nSalvar mesmo assim?`))return;const saved=await api(item?`/api/messages/${item.id}`:'/api/messages',{method:item?'PUT':'POST',body:JSON.stringify(data)});if(form.remove_attachment?.checked&&currentAttachment)await api(`/api/messages/${saved.id}/attachment`,{method:'DELETE'});const file=form.attachment_file.files[0];if(file)await uploadMessageAttachment(saved.id,file);closeModal();toast('✅ Mensagem salva e aplicada.');await renderMessages();},{wide:true,fullscreen:true,saveLabel:'💾 Salvar mensagem'});
  const form=$('#modal-form');const response=form.response_text;const validation=$('#message-validation');const captionMeter=$('#caption-meter');let validationTimer;
  const sourcePreview=()=>{const url=form.source_url.value.trim();if(!url)return'';const title=form.source_title.value.trim()||'Fonte oficial';const date=form.verified_at.value?form.verified_at.value.split('-').reverse().join('/'):'';return `🔎 *Fonte:* ${title}\n${response.value.includes(url)?'_Link oficial informado na resposta acima._':url}${date?`\n🗓️ *Verificada em:* ${date}`:''}`;};
  const updateCaptionMeter=()=>{const source=sourcePreview();const responseCount=response.value.trim().length;const sourceCount=source.length;const total=responseCount+(source?2+sourceCount:0);const hasAttachment=Boolean(form.attachment_file.files[0]||currentAttachment);const status=total>1024?'blocked':total>900?'warning':'safe';captionMeter.innerHTML=`<div class="validation-item ${status==='blocked'?'error':status==='warning'?'warning':'ok'}"><strong>Legenda com anexo</strong><br>Resposta: ${responseCount} caracteres · Fonte: ${sourceCount} · Total: ${total}<br>${hasAttachment?(status==='blocked'?'❌ Ultrapassa o limite de 1024. Mova conteúdo para “mais detalhes”.':status==='warning'?'⚠️ Dentro do limite, mas acima da faixa segura de 900.':'✅ Dentro do limite seguro.'):'ℹ️ O limite é aplicado quando houver anexo.'}</div>`;};
  const updatePreview=()=>{const source=sourcePreview();const text=[response.value,source].filter(Boolean).join('\n\n');$('#live-message-preview').innerHTML=renderWhatsAppMarkup(text,{groupName:'Grupo de Sistemas de Informação',senderName:'Maria'});const file=form.attachment_file.files[0];const attachment=file?.name||currentAttachment?.file_name||'';const ap=$('#live-attachment-preview');ap.hidden=!attachment;ap.textContent=attachment?`📎 ${attachment}`:'';updateCaptionMeter();};
  const runValidation=async()=>{clearTimeout(validationTimer);validationTimer=setTimeout(async()=>{try{const data=collectMessageForm(form,currentAttachment,item);const report=await api('/api/messages/validate',{method:'POST',body:JSON.stringify({id:item?.id||null,message:data})});validation.innerHTML=validationHtml(report);}catch(error){validation.innerHTML=`<div class="validation-item error">❌ ${esc(error.message)}</div>`;}},350);};
  form.addEventListener('input',()=>{updatePreview();runValidation();});form.addEventListener('change',()=>{updatePreview();runValidation();});$$('.insert-variable').forEach(btn=>btn.onclick=()=>insertAtCursor(response,btn.dataset.value));if($('#compare-origin-update'))$('#compare-origin-update').onclick=()=>{closeModal();openPackageUpdateModal(item.id);};updatePreview();runValidation();
}

async function historyModal(messageId){const entries=await api(`/api/messages/${messageId}/history`);const rows=entries.length?entries.map(entry=>`<article class="history-entry"><div class="toolbar"><div><strong>${fmtDate(entry.created_at)}</strong><p class="muted">${esc(entry.action)}</p></div><button class="button small restore-history" data-id="${entry.id}">↩️ Restaurar</button></div><p><strong>${esc(entry.snapshot.title||'')}</strong> · ${esc(scopeLabel(entry.snapshot.scope))}</p><div class="history-preview">${renderWhatsAppMarkup(entry.snapshot.response_text||'')}</div></article>`).join(''):'<div class="empty">Ainda não há versões anteriores.</div>';openInfoModal('Histórico de alterações',`<p class="muted">São mantidas as 50 versões anteriores mais recentes.</p><div class="history-list">${rows}</div>`);$$('.restore-history').forEach(btn=>btn.onclick=async()=>{if(!confirm('Restaurar esta versão? A versão atual também será guardada.'))return;await api(`/api/messages/${messageId}/history/${btn.dataset.id}/restore`,{method:'POST',body:'{}'});closeModal();toast('↩️ Versão restaurada.');await renderMessages();});}
function openSynonymManager(){const rows=state.synonyms.length?state.synonyms.map(group=>`<div class="backup-row"><div><strong>${esc(group.name)}</strong><span>${(group.terms||[]).map(esc).join(' · ')}</span></div><div class="row-actions"><button class="button small edit-synonym" data-id="${group.id}">✏️ Editar</button><button class="button small danger delete-synonym" data-id="${group.id}">🗑️</button></div></div>`).join(''):'<p class="muted">Nenhum grupo cadastrado.</p>';openInfoModal('Grupos de sinônimos',`<button class="button primary" id="add-synonym">➕ Novo grupo</button><div class="backup-list top-gap">${rows}</div>`);$('#add-synonym').onclick=()=>{closeModal();synonymModal();};$$('.edit-synonym').forEach(btn=>btn.onclick=()=>{const group=state.synonyms.find(x=>x.id===Number(btn.dataset.id));closeModal();synonymModal(group);});$$('.delete-synonym').forEach(btn=>btn.onclick=async()=>{if(!confirm('Excluir este grupo?'))return;try{await api(`/api/synonyms/${btn.dataset.id}`,{method:'DELETE'});state.synonyms=await api('/api/synonyms');toast('🗑️ Grupo excluído.');closeModal();openSynonymManager();}catch(error){toast(error.message,true);}});}
function synonymModal(item=null){openModal(item?'Editar grupo de sinônimos':'Novo grupo de sinônimos',`<div class="form-grid"><label class="full">Nome<input name="name" value="${esc(item?.name||'')}" required></label><label class="full">Palavras equivalentes<textarea name="terms" required>${esc((item?.terms||[]).join('\n'))}</textarea></label><label class="check full"><input name="active" type="checkbox" ${item?.active!==false?'checked':''}> Grupo ativo</label></div>`,async form=>{await api(item?`/api/synonyms/${item.id}`:'/api/synonyms',{method:item?'PUT':'POST',body:JSON.stringify({name:form.name.value,terms:list(form.terms.value),active:form.active.checked})});closeModal();state.synonyms=await api('/api/synonyms');toast('✅ Sinônimos salvos.');openSynonymManager();},{saveLabel:'💾 Salvar grupo'});}
function messageCsvModal(){const sample='title,tags,scope,sentences,keywords,require_question_mark,response_text,priority,active,publish\nContato de Bruno,"#contato|#professores",both,"qual o contato de bruno|email do bruno","bruno|contato",true,"📧 contato.bruno@example.invalid",50,true,true';openModal('Importar mensagens por CSV',`<p class="muted">Use | entre sentenças, palavras-chave ou etiquetas.</p><textarea class="csv-area" name="csv" required>${esc(sample)}</textarea>`,async form=>{const report=await api('/api/import/messages-csv',{method:'POST',body:JSON.stringify({csv:form.csv.value,publish:true})});closeModal();openInfoModal('Resultado da importação',`<div class="grid stats">${statCard('Criadas',report.created||0)}${statCard('Atualizadas',report.updated||0)}${statCard('Publicadas',report.published||0)}${statCard('Erros',report.errors?.length||0)}</div>${report.errors?.length?`<ul>${report.errors.map(e=>`<li>Linha ${e.line}: ${esc(e.error)}</li>`).join('')}</ul>`:'<p class="notice">✅ Importação concluída.</p>'}`);await renderMessages();},{saveLabel:'📥 Importar',wide:true});}

function professorScheduleImportModal(){
  openModal('Atualizar quadro docente',`<div class="import-intro"><p>Selecione um arquivo <strong>CSV, TSV ou XLSX</strong>. Cada linha deve conter professor, e-mail, disciplina, semestre, dia e horário.</p><p class="notice">Os cartões existentes mantêm todos os gatilhos personalizados e recebem uma versão no histórico antes da atualização.</p><a class="button small" href="/api/templates/professor-schedule.csv">⬇️ Baixar modelo CSV</a></div><div class="form-grid top-gap"><label>Período letivo padrão<input name="academic_period" placeholder="Ex.: 2027.1"><small>Usado quando a planilha não tiver a coluna “período letivo”.</small></label><label class="full">Arquivo do quadro docente<input name="schedule_file" type="file" accept=".csv,.tsv,.xlsx,text/csv,application/vnd.openxmlformats-officedocument.spreadsheetml.sheet" required></label></div>`,async form=>{
    const file=form.schedule_file.files[0];if(!file)throw new Error('Selecione o arquivo do quadro docente.');
    const response=await fetch('/api/import/professor-schedule/preview',{method:'POST',credentials:'same-origin',headers:{'X-File-Name':encodeURIComponent(file.name),'X-Academic-Period':encodeURIComponent(form.academic_period.value||'')},body:await file.arrayBuffer()});
    const payload=await response.json();if(!response.ok)throw new Error(payload.error||'Não foi possível ler a planilha.');state.teacherImportPreview=payload;closeModal();professorSchedulePreviewModal(payload);
  },{saveLabel:'🔎 Conferir atualização',wide:true});
}
function professorSchedulePreviewModal(payload){const preview=payload.preview||{};const rows=(preview.items||[]).map(item=>`<tr><td><strong>${esc(item.name)}</strong><br><small>${esc(item.email||'sem e-mail')}</small></td><td>${esc(item.academic_period||'—')}</td><td>${item.classes}</td><td>${item.action==='create'?badge('Criar','active'):badge('Atualizar','warning')}</td><td>${item.preserves_custom_triggers?'✅ Sim':'—'}</td></tr>`).join('');const warnings=[...(payload.errors||[]).map(error=>`Linha ${error.line}: ${error.error}`),...(preview.shared_disciplines||[]).map(name=>`A disciplina “${name}” aparece com mais de um professor; confira os gatilhos após a importação.`)];openModal('Confirmar quadro docente',`<div class="grid stats import-stats">${statCard('Professores',preview.total||0)}${statCard('Novos',preview.creates||0)}${statCard('Atualizados',preview.updates||0)}${statCard('Linhas válidas',payload.sourceRows||0)}</div>${warnings.length?`<div class="notice warn"><strong>Atenção</strong><ul>${warnings.map(value=>`<li>${esc(value)}</li>`).join('')}</ul></div>`:'<div class="notice">✅ Estrutura validada.</div>'}<div class="table-wrap teacher-import-table"><table><thead><tr><th>Professor</th><th>Período</th><th>Disciplinas</th><th>Ação</th><th>Preserva gatilhos</th></tr></thead><tbody>${rows}</tbody></table></div>`,async()=>{const report=await api('/api/import/professor-schedule/apply',{method:'POST',timeoutMs:20000,body:JSON.stringify({records:payload.records||[]})});closeModal();openInfoModal('Quadro docente atualizado',`<div class="grid stats">${statCard('Criados',report.created||0)}${statCard('Atualizados',report.updated||0)}${statCard('Gatilhos preservados',report.preservedTriggers||0)}${statCard('Erros',report.errors?.length||0)}</div>${report.errors?.length?`<ul>${report.errors.map(error=>`<li>${esc(error.professor)}: ${esc(error.error)}</li>`).join('')}</ul>`:'<p class="notice">✅ Cartões atualizados e versões anteriores salvas no histórico.</p>'}`);state.teacherImportPreview=null;await renderMessages();},{saveLabel:'📥 Aplicar atualização',wide:true});}
async function openPackageUpdateModal(id){const item=await api(`/api/messages/${Number(id)}`);const pending=item.pending_package_update;if(!pending){toast('Esta mensagem não possui atualização pendente.',true);return;}const current=item.draft||item;const triggerText=value=>[...(value?.sentences||[]),...(value?.keywords||[])].slice(0,12).join('\n')||'Sem gatilhos';openInfoModal('Comparar conteúdo do pacote',`<p class="muted">A atualização não foi aplicada automaticamente porque este cartão possui alterações locais.</p><div class="package-compare"><section><span class="badge custom">Sua versão</span><h3>${esc(current.title)}</h3><pre>${esc(current.response_text||'')}</pre><details><summary>Gatilhos atuais</summary><pre>${esc(triggerText(current.trigger))}</pre></details></section><section><span class="badge package">Versão nova do HUB</span><h3>${esc(pending.title)}</h3><pre>${esc(pending.response_text||'')}</pre><details><summary>Gatilhos do pacote</summary><pre>${esc(triggerText(pending.trigger))}</pre></details></section></div><div class="actions top-gap"><button class="button" id="keep-local-package">Manter minha versão</button><button class="button primary" id="use-package-update">Usar versão nova</button></div>`);$('#keep-local-package').onclick=async()=>{await api(`/api/messages/${id}/package-update`,{method:'POST',body:JSON.stringify({strategy:'keep'})});closeModal();toast('Sua versão foi mantida.');await renderMessages();};$('#use-package-update').onclick=async()=>{if(!confirm('Substituir o conteúdo local pela versão nova do HUB? A versão atual será preservada no histórico.'))return;await api(`/api/messages/${id}/package-update`,{method:'POST',body:JSON.stringify({strategy:'use'})});closeModal();toast('Versão nova aplicada.');await renderMessages();};}

function simpleDiagnosticSummary(event){const summary=String(event.summary||'');const missing=summary.match(/falt(?:ou|aram)[^.;]*/i);if(missing)return`Ignorada: ${missing[0].toLowerCase()}.`;if(event.outcome==='responded')return`Respondida pela regra “${event.matchedItem||'desconhecida'}”.`;if(event.outcome==='error')return`Erro: ${summary||'falha ao processar ou enviar.'}`;if(summary.includes('nenhuma regra')){const blocked=(event.details||[]).flatMap(x=>x.blockedReasons||[]);const keyword=blocked.find(x=>/falt|ausente|não encontrou/i.test(x));return keyword?`Ignorada: ${keyword}.`:'Ignorada: nenhuma regra satisfez todos os gatilhos.';}return`Ignorada: ${summary||'sem correspondência.'}`;}
function technicalDiagnostic(event){return`event_id=${event.id}\noutcome=${event.outcome}\nchat_type=${event.chatType}\nmatched_item=${event.matchedItem||''}\nrate_limit=${Boolean(event.rateLimited)}\n${(event.details||[]).map(item=>`rule_id=${item.id||''} title=${item.title} matched=${item.matched} score=${item.score} keyword_match=${item.keywordMatched||0}/${item.keywordTotal||0} scope=${item.scope} reasons=${(item.reasons||[]).join('|')} blocked=${(item.blockedReasons||[]).join('|')}`).join('\n')}`;}
function diagnosticDetails(details=[]){if(!details.length)return'';return`<details class="diagnostic-details"><summary>🔎 Regras analisadas (${details.length})</summary>${details.map(item=>`<div class="diagnostic-rule ${item.matched?'matched':'blocked'}"><strong>${item.matched?'✅':'⛔'} ${esc(item.title)}</strong><span>${Number(item.score||0).toFixed(1)} pts · ${esc(scopeLabel(item.scope))}</span><small>${esc([...(item.reasons||[]),...(item.blockedReasons||[])].join(' · ')||'sem detalhes')}</small></div>`).join('')}</details>`;}
function closeDiagnosticStream(){if(state.diagnosticStream){state.diagnosticStream.close();state.diagnosticStream=null;}}
function appendDiagnostic(event){state.diagnostics.push(event);if(state.diagnostics.length>500)state.diagnostics.splice(0,state.diagnostics.length-500);if(state.view==='diagnostics')drawDiagnostics();}
async function renderDiagnostics(){closeDiagnosticStream();state.diagnostics=await api('/api/diagnostics?limit=300');content.innerHTML=`<div class="toolbar"><div><h2>🔎 Mensagens recebidas e decisões</h2><p class="muted">Dados ficam somente na memória.</p></div><div class="actions"><div class="segmented"><button class="diag-mode ${state.diagnosticMode==='simple'?'active':''}" data-mode="simple">🙂 Modo simples</button><button class="diag-mode ${state.diagnosticMode==='technical'?'active':''}" data-mode="technical">🛠️ Modo técnico</button></div><label class="check compact"><input id="diag-auto" type="checkbox" checked> Ao vivo</label><button class="button danger" id="clear-diagnostics">🗑️ Limpar</button></div></div><div class="filter-row top-gap"><select id="diag-filter"><option value="all">Tudo</option><option value="responded">Respondidas</option><option value="ignored">Ignoradas</option><option value="error">Erros</option></select><input id="diag-search" class="search" placeholder="Filtrar"></div><div id="diagnostics-box" class="stack top-gap"></div>`;drawDiagnostics();$('#diag-filter').onchange=drawDiagnostics;$('#diag-search').oninput=drawDiagnostics;$$('.diag-mode').forEach(btn=>btn.onclick=()=>{state.diagnosticMode=btn.dataset.mode;localStorage.setItem('hub-diagnostic-mode',state.diagnosticMode);$$('.diag-mode').forEach(x=>x.classList.toggle('active',x===btn));drawDiagnostics();});$('#clear-diagnostics').onclick=async()=>{await api('/api/diagnostics',{method:'DELETE'});state.diagnostics=[];drawDiagnostics();};const stream=new EventSource('/api/diagnostics/stream');stream.onmessage=e=>{if($('#diag-auto')?.checked)appendDiagnostic(JSON.parse(e.data));};state.diagnosticStream=stream;}
function drawDiagnostics(){const box=$('#diagnostics-box');if(!box)return;const filter=$('#diag-filter')?.value||'all';const q=($('#diag-search')?.value||'').toLowerCase();const rows=[...state.diagnostics].reverse().filter(event=>(filter==='all'||event.outcome===filter)&&`${event.chatName} ${event.message} ${event.matchedItem} ${event.summary}`.toLowerCase().includes(q));box.innerHTML=rows.length?rows.map(event=>`<article class="card diagnostic-event ${esc(event.outcome)}"><div class="toolbar"><div class="tag-list">${badge(event.outcome||event.type,event.outcome==='responded'?'active':event.outcome==='error'?'warning':'inactive')}${badge(event.chatType==='group'?'👥 Grupo':'👤 Privado','scope')}</div><span class="muted">${fmtDate(event.createdAt)}</span></div><h3>${esc(event.chatName||'Conversa')}</h3><p><strong>Mensagem:</strong> ${esc(event.message)}</p>${state.diagnosticMode==='simple'?`<p class="diagnostic-simple">${esc(simpleDiagnosticSummary(event))}</p>`:`<pre class="technical-diagnostic">${esc(technicalDiagnostic(event))}</pre>${diagnosticDetails(event.details||[])}`}${event.reply?`<div class="whatsapp-preview">${renderWhatsAppMarkup(event.reply)}</div>`:''}</article>`).join(''):'<div class="card empty">Nenhum evento.</div>';}

async function renderCalculators(){state.calculators=await api('/api/calculators');content.innerHTML=`<div class="grid cards-3">${state.calculators.map(item=>`<article class="card"><div class="toolbar"><div>${badge(item.enabled?'Ativa':'Inativa',item.enabled?'active':'inactive')}<h3>${esc(item.label)}</h3></div><button class="button small edit-calc" data-key="${esc(item.key)}">✏️ Editar</button></div><code class="command-code">${esc(item.command)}</code><p class="muted">${esc(item.description)}</p></article>`).join('')}</div>`;$$('.edit-calc').forEach(btn=>btn.onclick=()=>calculatorModal(state.calculators.find(x=>x.key===btn.dataset.key)));}
function calculatorModal(item){openModal('Configurar calculadora',`<div class="form-grid"><label class="full">Nome<input name="label" value="${esc(item.label)}" required></label><label class="full">Comando e aliases separados por |<input name="command" value="${esc(item.command)}" required></label><label class="full">Descrição<textarea name="description">${esc(item.description)}</textarea></label><label class="check"><input name="enabled" type="checkbox" ${item.enabled?'checked':''}> Calculadora ativa</label></div>`,async form=>{await api(`/api/calculators/${encodeURIComponent(item.key)}`,{method:'PUT',body:JSON.stringify({label:form.label.value,command:form.command.value,description:form.description.value,enabled:form.enabled.checked,config:item.config})});closeModal();toast('🧮 Calculadora atualizada.');await renderCalculators();});}
async function renderGroups(){state.groups=await api('/api/groups');content.innerHTML=`<div class="toolbar"><p class="muted">A sincronização é automática após conectar.</p><button class="button primary" id="sync-groups">🔄 Sincronizar agora</button></div><div id="groups-box"></div>`;drawGroups();$('#sync-groups').onclick=async()=>{const r=await api('/api/groups/sync',{method:'POST',body:'{}'});toast(`✅ ${r.synced} grupo(s) sincronizado(s).`);await renderGroups();};}
function toggleCell(group,field,label){return`<label class="permission-check"><input class="group-permission" data-id="${esc(group.whatsapp_id)}" data-field="${field}" type="checkbox" ${group[field]?'checked':''}><span>${esc(label)}</span></label>`;}
function drawGroups(){const box=$('#groups-box');if(!state.groups.length){box.innerHTML='<div class="card empty">Conecte o WhatsApp para detectar os grupos.</div>';return;}box.innerHTML=`<div class="table-wrap"><table class="permissions-table"><thead><tr><th>Grupo</th><th>Atendido</th><th>Ajuda</th><th>Mensagens</th><th>Calculadoras</th><th>Última detecção</th></tr></thead><tbody>${state.groups.map(g=>`<tr><td><strong>${esc(g.name||'Grupo sem nome')}</strong><br><small>${esc(g.whatsapp_id)}</small></td><td>${toggleCell(g,'enabled','Atendido')}</td><td>${toggleCell(g,'allow_help','Ajuda')}</td><td>${toggleCell(g,'allow_messages','Mensagens')}</td><td>${toggleCell(g,'allow_calculator','Calculadoras')}</td><td>${fmtDate(g.last_seen_at)}</td></tr>`).join('')}</tbody></table></div>`;box.querySelectorAll('.group-permission').forEach(input=>input.onchange=async()=>{const group=state.groups.find(g=>g.whatsapp_id===input.dataset.id);group[input.dataset.field]=input.checked;try{Object.assign(group,await api(`/api/groups/${encodeURIComponent(group.whatsapp_id)}`,{method:'PUT',body:JSON.stringify(group)}));toast('✅ Permissões atualizadas.');}catch(e){input.checked=!input.checked;toast(e.message,true);}});}
async function renderAnalytics(days=30){state.analytics=await api(`/api/analytics?days=${days}`);const a=state.analytics;const max=Math.max(1,...(a.top||[]).map(i=>Number(i.count)));content.innerHTML=`<div class="toolbar"><p class="muted">Somente contagens por tópico.</p><div class="actions"><select id="analytics-days"><option value="7">7 dias</option><option value="30" ${days===30?'selected':''}>30 dias</option><option value="90">90 dias</option><option value="365">1 ano</option></select><button class="button danger" id="clear-analytics">🗑️ Zerar</button></div></div><div class="grid stats">${statCard('Interações',a.total||0)}${statCard('Tópicos',a.top?.length||0)}${statCard('Desde',a.since)}${statCard('Período',`${a.days} dias`)}</div><div class="card"><h3>Mensagens mais usadas</h3>${a.top?.length?`<div class="analytics-bars">${a.top.map(i=>`<div class="analytics-row"><div><strong>${esc(i.topic)}</strong><small>${esc(i.match_type)}</small></div><div class="bar-track"><span style="width:${Math.max(3,Number(i.count)/max*100)}%"></span></div><b>${i.count}</b></div>`).join('')}</div>`:'<div class="empty">Sem dados.</div>'}</div>`;$('#analytics-days').onchange=e=>renderAnalytics(Number(e.target.value));$('#clear-analytics').onclick=async()=>{if(!confirm('Apagar as estatísticas?'))return;await api('/api/analytics',{method:'DELETE'});await renderAnalytics(days);};}

function dashboardOptions(selected){const labels={connection:'📱 Conexão',messages:'💬 Quantidade de mensagens',queue:'📤 Filas por conversa',last_reply:'🕒 Atividade recente',top_rules:'📈 Regras mais usadas',errors:'🚨 Erros recentes',memory:'🧠 Recursos'};return Object.entries(labels).map(([key,label])=>`<label class="check dashboard-option"><input type="checkbox" name="dashboard_card" value="${key}" ${selected.includes(key)?'checked':''}> ${label}</label>`).join('');}
async function renderSettings(){const[s,backups,update]=await Promise.all([api('/api/settings'),api('/api/backups'),api('/api/update')]);state.settings=s;state.backups=backups;const selected=String(s.dashboard_cards||'').split(',').filter(Boolean);content.innerHTML=`<form id="settings-form" class="settings-form wide"><div class="card settings-section"><h3>💬 Automação</h3><div class="form-grid"><label>Nome do bot<input name="bot_name" value="${esc(s.bot_name||'')}"></label><label>Antirrepetição por pessoa (segundos)<input name="cooldown_seconds" type="number" min="0" max="3600" value="${esc(s.cooldown_seconds||'0')}"><small>Use 0 para nunca ignorar uma nova pergunta.</small></label><label class="check"><input name="automatic_messages_enabled" type="checkbox" ${bool(s.automatic_messages_enabled)?'checked':''}> Mensagens automáticas habilitadas</label><label class="check"><input name="calculator_enabled" type="checkbox" ${bool(s.calculator_enabled)?'checked':''}> Calculadoras habilitadas</label><label class="check"><input name="quote_replies" type="checkbox" ${bool(s.quote_replies)?'checked':''}> Citar a mensagem original</label><label class="check"><input name="bot_paused" type="checkbox" ${bool(s.bot_paused)?'checked':''}> Pausar automações públicas</label><label class="full">Rodapé apenas para ajuda e calculadoras<textarea name="reply_footer">${esc(s.reply_footer||'')}</textarea></label></div></div>
  <div class="card settings-section"><h3>🔁 Proteção contra ciclos entre bots</h3><div class="form-grid"><label class="full">Números de outros bots<textarea name="ignored_bot_numbers" placeholder="5577999999999">${esc(s.ignored_bot_numbers||'')}</textarea><small>Um por linha ou separados por vírgula.</small></label><label class="full">Marcadores de mensagens de bot<textarea name="ignored_message_prefixes" placeholder="[BOT]\n[HUBBOT]">${esc(s.ignored_message_prefixes||'')}</textarea><small>Mensagens que começarem com um desses marcadores serão ignoradas.</small></label></div></div>
  <div class="card settings-section"><h3>🏠 Painel inicial configurável</h3><p class="muted">O resumo permanente do topo continua sempre visível.</p><div class="dashboard-options">${dashboardOptions(selected.length?selected:DEFAULT_DASHBOARD_CARDS)}</div><label class="top-gap">Alertar ausência de mensagens após (minutos)<input name="dashboard_stale_minutes" type="number" min="10" max="10080" value="${esc(s.dashboard_stale_minutes||'120')}"></label></div>
  <div class="card settings-section"><h3>👥 Conversas e privacidade</h3><div class="form-grid"><label>Grupos atendidos<select name="group_mode"><option value="all" ${s.group_mode==='all'?'selected':''}>Todos</option><option value="selected" ${s.group_mode==='selected'?'selected':''}>Somente selecionados</option></select></label><label>Retenção dos registros (dias)<input name="log_retention_days" type="number" min="0" max="3650" value="${esc(s.log_retention_days||'30')}"></label><label class="check"><input name="log_matched_messages" type="checkbox" ${bool(s.log_matched_messages)?'checked':''}> Registrar respostas</label><label class="check"><input name="diagnostic_enabled" type="checkbox" ${bool(s.diagnostic_enabled)?'checked':''}> Diagnóstico em tempo real</label><label class="check"><input name="usage_statistics_enabled" type="checkbox" ${bool(s.usage_statistics_enabled)?'checked':''}> Estatísticas anônimas</label></div></div>
  <div class="card settings-section"><h3>⚡ Entrega de respostas</h3><div class="notice"><strong>Fila por conversa ativada</strong><p>Mensagens do mesmo grupo ou privado são respondidas na ordem em que chegaram. Conversas diferentes continuam em paralelo, sem intervalo artificial.</p></div><div class="form-grid top-gap"><label class="check full"><input name="process_append_messages" type="checkbox" ${bool(s.process_append_messages)?'checked':''}> Responder também a mensagens recuperadas após reconexão</label></div><p class="muted">O bot só pausa envios quando o próprio WhatsApp devolve um bloqueio temporário.</p></div>
  <div class="card settings-section"><h3>🧭 Conflitos e administradores</h3><div class="form-grid"><label class="check"><input name="disambiguation_enabled" type="checkbox" ${bool(s.disambiguation_enabled)?'checked':''}> Pedir escolha em empate</label><label>Diferença máxima<input name="disambiguation_threshold" type="number" min="0" max="20" step="0.1" value="${esc(s.disambiguation_threshold||'1')}"></label><label>Tempo para escolher (s)<input name="disambiguation_timeout_seconds" type="number" min="30" max="600" value="${esc(s.disambiguation_timeout_seconds||'120')}"></label><label class="full">Números administradores<textarea name="admin_numbers">${esc(s.admin_numbers||'')}</textarea></label></div></div>
  <div class="card settings-section"><h3>💾 Backups e atualizações</h3><div class="form-grid"><label class="check"><input name="automatic_backups_enabled" type="checkbox" ${bool(s.automatic_backups_enabled)?'checked':''}> Backups automáticos JSON</label><label>Intervalo (horas)<input name="backup_interval_hours" type="number" min="1" value="${esc(s.backup_interval_hours||'24')}"></label><label>Quantidade mantida<input name="backup_keep_count" type="number" min="1" value="${esc(s.backup_keep_count||'14')}"></label></div><div class="actions top-gap"><button type="button" class="button" id="run-backup">💾 Criar JSON</button><button type="button" class="button primary" id="full-backup">📦 Backup completo ZIP</button><button type="button" class="button" id="restore-backup">📤 Restaurar JSON</button><button type="button" class="button" id="install-update">⬆️ Instalar ZIP</button></div><p class="muted">O backup completo inclui banco, configurações, histórico e anexos. A sessão do WhatsApp é opcional e sensível.</p><p class="muted">Versão atual: ${esc(update.currentVersion||'0.9.8')}</p><div id="backup-list"></div></div>
  <div class="card settings-section"><h3>🔐 Alterar senha</h3><div class="form-grid"><label>Senha atual<input id="current-password" type="password"></label><label>Nova senha<input id="new-password" type="password" minlength="10"></label></div><button type="button" class="button top-gap" id="change-password">🔐 Alterar senha</button></div><button class="button primary" type="submit">💾 Salvar configurações</button></form>`;
  $('#settings-form').onsubmit=async e=>{e.preventDefault();const data=Object.fromEntries(new FormData(e.target).entries());['automatic_messages_enabled','calculator_enabled','quote_replies','bot_paused','log_matched_messages','diagnostic_enabled','usage_statistics_enabled','disambiguation_enabled','automatic_backups_enabled','risk_guard_enabled','process_append_messages'].forEach(k=>data[k]=e.target.elements[k]?.checked||false);data.dashboard_cards=$$('input[name="dashboard_card"]:checked').map(x=>x.value).join(',');await api('/api/settings',{method:'PUT',body:JSON.stringify(data)});state.settings={...state.settings,...data};renderStatus();toast('💾 Configurações salvas.');};
  $('#run-backup').onclick=async()=>{await api('/api/backups/run',{method:'POST',body:'{}'});toast('💾 Backup criado.');await renderSettings();};$('#restore-backup').onclick=()=>$('#restore-file').click();$('#install-update').onclick=()=>$('#update-file').click();
  $('#full-backup').onclick=()=>{const includeSession=confirm('Incluir a sessão do WhatsApp?\n\nEla permite reutilizar a conexão, mas torna o ZIP extremamente sensível.\n\nOK = incluir sessão\nCancelar = backup sem sessão');window.location.href=`/api/backup/full?session=${includeSession?'1':'0'}`;};
  $('#change-password').onclick=async()=>{await api('/api/security/password',{method:'POST',body:JSON.stringify({current_password:$('#current-password').value,new_password:$('#new-password').value})});showLogin('Senha alterada. Entre novamente.');};drawBackups();
}
function drawBackups(){const box=$('#backup-list');const files=state.backups?.files||[];box.innerHTML=files.length?`<div class="backup-list top-gap">${files.slice(0,8).map(f=>`<div class="backup-row"><div><strong>${fmtDate(f.createdAt)}</strong><span>${fmtBytes(f.sizeBytes)}</span></div><div class="row-actions"><a class="button small" href="/api/backups/${encodeURIComponent(f.name)}/download">⬇️ Baixar</a><button class="button small danger delete-backup" data-name="${esc(f.name)}">🗑️</button></div></div>`).join('')}</div>`:'<p class="muted top-gap">Nenhum backup.</p>';box.querySelectorAll('.delete-backup').forEach(btn=>btn.onclick=async()=>{await api(`/api/backups/${encodeURIComponent(btn.dataset.name)}`,{method:'DELETE'});await renderSettings();});}
async function renderLogs(){state.logs=await api('/api/logs');content.innerHTML=`<div class="toolbar"><p class="muted">Registros das respostas emitidas.</p><button class="button danger" id="clear-logs">🗑️ Limpar</button></div><div class="card">${state.logs.length?state.logs.map(log=>`<article class="log-item"><div class="log-meta">${badge(log.match_type)}<strong>${esc(log.chat_name||'Conversa')}</strong><span>${fmtDate(log.created_at)}</span><span>→ ${esc(log.matched_item)}</span></div><p><strong>Mensagem:</strong> ${esc(log.message_excerpt)}</p><p class="muted"><strong>Resposta:</strong> ${esc(log.reply_excerpt)}</p></article>`).join(''):'<div class="empty">Nenhum registro.</div>'}</div>`;$('#clear-logs').onclick=async()=>{if(!confirm('Limpar todos os registros?'))return;await api('/api/logs',{method:'DELETE'});await renderLogs();};}

$('#restore-file').onchange=async event=>{const file=event.target.files[0];if(!file)return;if(!confirm('Substituir os dados administrativos pelo backup?'))return;try{await api('/api/restore',{method:'POST',body:await file.text()});toast('✅ Backup restaurado.');await loadAll();}catch(e){toast(e.message,true);}finally{event.target.value='';}};
$('#update-file').onchange=async event=>{const file=event.target.files[0];if(!file)return;if(!confirm(`Instalar ${file.name}?`))return;try{const response=await fetch('/api/update/upload',{method:'POST',credentials:'same-origin',headers:{'Content-Type':'application/zip','X-Update-Filename':encodeURIComponent(file.name)},body:await file.arrayBuffer()});const payload=await response.json();if(!response.ok)throw new Error(payload.error||'Falha ao atualizar.');toast(payload.message||'Atualização iniciada.');}catch(e){toast(e.message,true);}finally{event.target.value='';}};

function openModal(title,body,onSubmit,options={}){$('#modal-content').innerHTML=`<div class="modal-head"><div><p class="eyebrow">EDIÇÃO</p><h2>${esc(title)}</h2></div><div class="actions">${options.fullscreen?'<button type="button" class="icon-button" id="expand-modal" title="Tela cheia">⛶</button>':''}<button type="button" class="icon-button" id="close-modal">✖️</button></div></div><form id="modal-form">${body}<div class="modal-actions"><button type="button" class="button" id="cancel-modal">↩️ Cancelar</button><button type="submit" class="button primary">${esc(options.saveLabel||'💾 Salvar')}</button></div></form>`;modal.classList.toggle('wide-modal',Boolean(options.wide));modal.showModal();$('#close-modal').onclick=closeModal;$('#cancel-modal').onclick=closeModal;if($('#expand-modal'))$('#expand-modal').onclick=()=>{modal.classList.toggle('fullscreen-modal');$('#expand-modal').textContent=modal.classList.contains('fullscreen-modal')?'🗗':'⛶';};$('#modal-form').onsubmit=async e=>{e.preventDefault();try{await onSubmit(e.target);}catch(error){toast(error.message,true);}};}
function openInfoModal(title,body){$('#modal-content').innerHTML=`<div class="modal-head"><div><p class="eyebrow">RESULTADO</p><h2>${esc(title)}</h2></div><button type="button" class="icon-button" id="close-modal">✖️</button></div>${body}<div class="modal-actions"><button class="button primary" id="cancel-modal">✅ Fechar</button></div>`;modal.classList.remove('wide-modal','fullscreen-modal');modal.showModal();$('#close-modal').onclick=closeModal;$('#cancel-modal').onclick=closeModal;}
function closeModal(){modal.close();modal.classList.remove('wide-modal','fullscreen-modal');}
modal.onclick=e=>{if(e.target===modal)closeModal();};

(async()=>{try{const[settings,status]=await Promise.all([api('/api/settings'),api('/api/status')]);state.settings=settings;state.status=status;renderStatus();await render();showApp();}catch{showLogin();}})();
// SSE entrega alterações imediatamente. O polling lento é apenas contingência.
setInterval(()=>{if(!document.hidden)refreshStatus();},60000);
const resumePanel=()=>{if(document.hidden)return;renderStatus();refreshStatus();};
document.addEventListener('visibilitychange',resumePanel);window.addEventListener('pageshow',resumePanel);window.addEventListener('online',resumePanel);
